window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[44]={"id":"044","numero":44,"titre":"Tuméfaction pelvienne chez la femme","objectifs":[{"id":"44-1","rang":"A","rubrique":"Étiologies","titre":"Connaître les 2 étiologies les plus fréquentes de tuméfaction pelvienne","contenu":"<div class=\"notion-course\"><p>Devant toute <span>tuméfaction</span> pelvienne chez une femme en âge de procréer, le <strong>premier réflexe</strong> est d’<strong><span class=\"nc-yellow_bg\">éliminer une </span><span><span class=\"nc-yellow_bg\">grossesse</span></span></strong> par dosage de <span><span class=\"nc-pink nc-bold\">β-hCG</span></span> (un <strong><span class=\"nc-green_bg\">utérus gravide</span></strong> est <em>augmenté de volume et mou</em> dans un contexte de retard de règles).</p>\n\n      <p>Une fois la <span>grossesse</span> écartée, les <strong>2 étiologies les plus fréquentes</strong> sont :</p>\n\n      <table>\n        <thead>\n          <tr><th>Étiologie</th><th>Origine</th><th>Repère clé</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"nc-yellow_bg\">Fibrome utérin</span></strong></td>\n            <td>Utérine</td>\n            <td>Tumeur utérine <strong>la plus fréquente</strong> · <span><span class=\"nc-yellow_bg\">masse</span></span><span class=\"nc-yellow_bg\"> </span><span><span class=\"nc-yellow_bg\">dépendante de l’utérus</span></span> au <span>TV</span></td>\n          </tr>\n          <tr>\n            <td><strong><span><span class=\"nc-orange_bg\">Kyste de l’ovaire</span></span></strong></td>\n            <td>Ovarienne</td>\n            <td><span>Masse</span> <span>latéro-utérine indépendante</span> de l’utérus · ± complications (torsion, hémorragie, <span>rupture</span>)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> <span><span class=\"nc-pink nc-bold\">β-hCG</span></span> systématique → puis <strong><span class=\"nc-yellow_bg\">fibrome utérin</span></strong> et <strong>kyste ovarien</strong> en tête. L’<span><span class=\"nc-blue_bg\">échographie pelvienne</span></span> est l’examen clé pour les départager (cf. obj-10).\n      </div></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/rpc/\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Recommandations pour la pratique clinique</a></li></ul></details>","frequence":0},{"id":"44-2","rang":"A","rubrique":"Étiologies","titre":"Connaître les autres causes de tuméfaction pelvienne","contenu":"<div class=\"notion-course\"><p>Au-delà de la <span><span class=\"nc-green_bg\">grossesse</span></span>, du fibrome et du kyste ovarien, les autres causes se classent <strong>par organe</strong>.</p>\n\n      <table>\n        <thead>\n          <tr><th>Origine</th><th>Étiologies</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Utérine</strong></td>\n            <td>\n              · <strong><span><span class=\"nc-red_bg\">Sarcome</span> / léiomyosarcome</span></strong> : rare, surtout après la ménopause, <span>masse</span> à <span><span class=\"nc-red nc-bold\">progression rapide</span></span><br>\n              · <strong><span><span class=\"nc-brown_bg\">Adénomyose</span></span></strong> : <span class=\"nc-brown_bg\">rarement</span> (utérus ne dépasse pas le double de sa taille)<br>\n              · <strong><span>Cancer de l’endomètre</span></strong> : exceptionnellement (surtout <span class=\"nc-red nc-bold\">si tumeur endocavitaire avec sténose du col</span> → <span><span class=\"nc-blue nc-bold\">hématométrie</span></span> ± <span class=\"nc-blue nc-bold\">pyométrie</span>)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Ovarienne</strong></td>\n            <td>· <strong><span><span class=\"nc-purple_bg\">Abcès ovarien</span></span></strong> (post-pelvipéritonite, <span>ponction</span>)<br>· <strong><span><span class=\"nc-orange_bg\">Endométriome</span></span></strong><br>· <span><span class=\"nc-orange_bg\">Cancer de l’ovaire</span></span> (rare avant la ménopause)</td>\n          </tr>\n          <tr>\n            <td><strong>Tubaire</strong></td>\n            <td>· <strong><span><span class=\"nc-orange_bg\">Hydrosalpinx</span></span></strong> · <span class=\"nc-orange_bg\">bloc adhérentiel post-</span><span><span class=\"nc-orange_bg\">infectieux</span></span> · kyste paratubaire / vestigial<br><em>(la trompe se dilate <span class=\"nc-brown_bg\">rarement</span> assez pour donner une <span>masse</span> — souvent masse annexielle infectieuse mixte trompe + ovaire)</em></td>\n          </tr>\n          <tr>\n            <td><strong>Péritonéale</strong></td>\n            <td><span class=\"nc-orange_bg\">Endométriose du cul-de-sac recto-utérin</span> → plutôt <em><span class=\"nc-blue nc-bold\">induration</span> / <span><span class=\"nc-blue nc-bold\">nodule</span></span></em> qu’une vraie <span>masse</span></td>\n          </tr>\n          <tr>\n            <td><strong>Digestive</strong> (rares)</td>\n            <td><span class=\"nc-orange_bg\">Sigmoïdite</span> · <span>cancer colo-rectal</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong><span>Drapeau rouge</span>.</strong> Une <span>masse</span> pelvienne <em>irrégulière, fixée, à <span class=\"nc-red nc-bold\">progression rapide</span></em>, surtout <strong>après la ménopause</strong> ou avec <span>ascite</span>, fait évoquer une <span>tumeur maligne</span> (ovaire, <span class=\"nc-red_bg\">sarcome</span>, endomètre) jusqu’à preuve du contraire.\n      </div></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/rpc/\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Recommandations pour la pratique clinique</a></li></ul></details>","frequence":2},{"id":"44-3","rang":"B","rubrique":"Epidémiologie","titre":"Fréquence des fibromes et des kystes ovariens bénins","contenu":"<div class=\"notion-course\"><h4><span class=\"nc-yellow_bg\">Fibrome utérin</span></h4>\n      <table>\n        <thead>\n          <tr><th>Item</th><th>Donnée</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span>Prévalence</span></strong></td>\n            <td>Augmente avec l’âge : <span>20–30 %</span> des femmes après <span>35 ans</span> · <span>50 %</span> à<span> 50 ans</span></td>\n          </tr>\n          <tr>\n            <td><strong><span>Évolution</span> spontanée</strong></td>\n            <td>Imprévisible · <strong>régression habituelle après la ménopause</strong></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Kystes ovariens bénins</h4>\n      <table>\n        <thead>\n          <tr><th>Item</th><th>Donnée</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span>Terrain</span></strong></td>\n            <td>Très fréquents pendant la <strong>période d’activité génitale</strong> · l’immense majorité sont des <strong>kystes fonctionnels</strong> bénins</td>\n          </tr>\n          <tr>\n            <td><strong><span>Évolution</span></strong></td>\n            <td>La plupart <strong>régressent spontanément</strong> (contrôle échographique à <span>3 mois</span>) · la persistance &gt; <span>3 mois</span> fait évoquer un kyste <strong>organique</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Bénin <span>vs</span> malin</strong></td>\n            <td>Les tumeurs <span>malignes</span> de l’ovaire restent <strong>rares avant la ménopause</strong> · l’épithélial représente <span>~ 90 %</span> des tumeurs organiques (cf. item 306)</td>\n          </tr>\n        </tbody>\n      </table></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/rpc/\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Recommandations pour la pratique clinique</a></li></ul></details>","frequence":0},{"id":"44-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les symptômes et les éléments de l’examen clinique liés aux fibromes","contenu":"<div class=\"notion-course\"><p><span>~ 50 %</span> des fibromes sont <strong>asymptomatiques</strong>, découverts fortuitement à l’examen ou en imagerie. Quand ils s’expriment, trois grands tableaux dominent.</p>\n\n      <h4>1 · Saignements utérins anormaux — signe le plus fréquent</h4>\n\n      <ul>\n        <li><strong><span><span class=\"nc-yellow_bg\">Ménorragies</span></span></strong> (souvent polyménorrhée) : règles <span><span class=\"nc-pink nc-bold\">&gt; 6 jours</span></span> et/ou <span><span class=\"nc-pink nc-bold\">&gt; 80 mL</span></span></li>\n        <li><strong><span>Métrorragies</span></strong> : rares isolées, plutôt <em>ménométrorragies</em></li>\n        <li><strong><span>Score de Higham</span> &gt; 100</strong> = <span class=\"nc-yellow_bg\">ménorragies</span> (nombre de changes + caillots)</li>\n        <li>Complication : <span><span class=\"nc-red nc-bold\">anémie ferriprive</span></span>, parfois profonde</li>\n      </ul>\n\n      <p><em>Quels fibromes saignent le plus ?</em></p>\n      <ul>\n        <li><strong>Sous-muqueux (FIGO 0–2)</strong> : <em><span class=\"nc-red nc-bold\">le plus souvent</span></em>, action directe sur la muqueuse endométriale</li>\n        <li><strong>Interstitiels (FIGO 3–4)</strong> : <em>plus rarement</em>, altération de la contractilité du myomètre</li>\n        <li><strong>Sous-séreux (FIGO 5–7)</strong> : <em>rarement</em> à l’origine d’hémorragies</li>\n      </ul>\n\n      <h4>2 · <span class=\"nc-blue nc-bold\">Syndrome de </span><span><span class=\"nc-blue nc-bold\">masse</span></span><span class=\"nc-blue nc-bold\"> pelvienne</span></h4>\n\n      <p>Apparition <strong>progressive</strong>, sans douleur vraie : <span>pesanteur</span> pelvienne, <span><span class=\"nc-blue_bg\">masse</span></span><span class=\"nc-blue_bg\"> abdominale</span>, <span class=\"nc-blue_bg\">augmentation du volume de l’abdomen</span>.</p>\n\n      <p>Complications par <strong>compression d’organes de voisinage</strong> :</p>\n      <ul>\n        <li><strong><span class=\"nc-red nc-bold\">Vésicale</span></strong> : <span>pollakiurie</span> par irritation, <span class=\"nc-orange_bg\">rétention d’urines</span></li>\n        <li><strong><span class=\"nc-red nc-bold\">Urétérale</span></strong> : <span class=\"nc-blue_bg\">urétéro-hydronéphrose</span>, <span class=\"nc-orange_bg\">coliques néphrétiques</span>, <span class=\"nc-orange_bg\">pyélonéphrites</span></li>\n        <li><strong><span class=\"nc-red nc-bold\">Digestive</span></strong> : <span><span class=\"nc-blue_bg\">constipation</span></span>, <span class=\"nc-blue_bg\">faux besoins par compression rectale</span></li>\n        <li><strong><span class=\"nc-red nc-bold\">Veineuse pelvienne</span></strong> : <span><span class=\"nc-blue_bg\">œdèmes des membres inférieurs</span></span>, <span><span class=\"nc-orange_bg\">TVP</span></span></li>\n        <li><strong><span class=\"nc-red nc-bold\">Nerveuse</span></strong> : <span class=\"nc-orange_bg\">sciatalgie</span> (face postérieure cuisse), <span class=\"nc-orange_bg\">névralgie obturatrice</span> (face interne cuisse)</li>\n      </ul>\n\n      <p><em><span class=\"nc-orange_bg\">Fibromes</span> à risque de <span>masse</span> pelvienne :</em> <span class=\"nc-red_bg nc-bold\">volumineux</span> <span>&gt; 5 cm</span> · <span class=\"nc-orange_bg nc-bold\">sous-séreux</span> (FIGO 5–7).</p>\n\n      <h4>3 · Dysménorrhée</h4>\n\n      <p>Possible si <strong>fibrome du col ou de l’isthme</strong> (FIGO 8) — gêne l’évacuation du flux menstruel.</p>\n\n      <h4>Examen clinique — <span>TV</span></h4>\n\n      <ul>\n        <li><span class=\"nc-orange_bg\">Fibromes</span> palpables = souvent <strong><span class=\"nc-brown_bg\">interstitiels</span> (3–4)</strong> ou <strong><span class=\"nc-brown_bg\">sous-séreux</span> (5–7)</strong></li>\n        <li><strong>Utérus augmenté de volume</strong> : <span class=\"nc-orange_bg\">fibromes interstitiels ou sous-séreux</span></li>\n        <li><strong><span>Masse</span> latéro-utérine dépendante de l’utérus</strong> : <span class=\"nc-orange_bg\">fibrome sous-séreux sessile</span></li>\n        <li><strong><span>Masse</span> latéro-utérine indépendante</strong> : <span class=\"nc-orange_bg\">fibrome pédiculé</span></li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Devant des <em>ménométrorragies + utérus polymyomateux palpable au <span>TV</span></em>, doser <strong><span>NFS</span> (<span class=\"nc-red nc-bold\">anémie ferriprive</span>) + <span>ferritine</span></strong>, faire une <strong><span><span class=\"nc-blue_bg\">échographie</span></span><span class=\"nc-blue_bg\"> pelvienne</span></strong> et apprécier le <span>score</span> de Higham.\n      </div></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/rpc/\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Recommandations pour la pratique clinique</a></li></ul></details>","frequence":1,"liens":[{"href":"https://radiopaedia.org/articles/uterine-leiomyoma","label":"Radiopaedia : Uterine leiomyoma"},{"href":"https://radiopaedia.org/articles/figo-classification-system-foruterine-leiomyoma","label":"Radiopaedia : Classification FIGO des fibromes utérins"}]},{"id":"44-5","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître les principales complications des fibromes","contenu":"<div class=\"notion-course\"><h4>Complications douloureuses aiguës</h4>\n\n      <ul>\n        <li><strong><span><span class=\"nc-yellow_bg\">Nécrobiose aseptique</span></span></strong> = principale cause de douleur du fibrome</li>\n        <li><strong><span class=\"nc-orange_bg\">Torsion</span></strong><span class=\"nc-orange_bg\"> d’un fibrome sous-séreux pédiculé</span> (FIGO 7, plus rare)</li>\n        <li><strong>Accouchement par le col</strong> d’un <span class=\"nc-orange_bg\">fibrome pédiculé</span> sous-muqueux avec coliques expulsives (plus rare)</li>\n      </ul>\n\n      <h4><span>Nécrobiose aseptique</span> de fibrome — tableau clinique</h4>\n\n      <table>\n        <thead>\n          <tr><th>Item</th><th>Caractéristique</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Cause</strong></td>\n            <td><strong><span class=\"nc-red nc-bold\">Ischémie du fibrome</span></strong></td>\n          </tr>\n          <tr>\n            <td><strong>Contexte</strong></td>\n            <td>Encore plus fréquente lors de la <strong><span><span class=\"nc-pink_bg\">grossesse</span></span></strong> et du <strong><span class=\"nc-pink_bg\">post-partum</span></strong></td>\n          </tr>\n          <tr>\n            <td><strong>Symptômes</strong></td>\n            <td>\n              <span><span class=\"nc-blue_bg\">Fièvre</span></span><span class=\"nc-blue_bg\"> </span><span><span class=\"nc-blue_bg\">38–39 °C</span></span><br>\n              <span class=\"nc-yellow_bg\">Douleurs pelviennes</span> <strong>intenses</strong><br>\n              <span><span class=\"nc-yellow_bg\">Métrorragies</span></span><span class=\"nc-yellow_bg\"> de sang</span> <strong><span class=\"nc-yellow_bg nc-bold\">noirâtre</span></strong> (parfois)\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span>TV</span></strong></td>\n            <td><span class=\"nc-blue_bg\">Augmentation du volume du fibrome</span> · douloureux à la palpation</td>\n          </tr>\n          <tr>\n            <td><strong><span>Échographie</span></strong></td>\n            <td><span class=\"nc-blue_bg\">Image en </span><em><span class=\"nc-blue_bg\">« cocarde »</span></em> avec <strong><span class=\"nc-blue nc-bold\">hyperéchogénicité centrale</span></strong></td>\n          </tr>\n          <tr>\n            <td><strong>Traitement</strong></td>\n            <td>\n              <strong>Médical</strong> :<br>\n              · Repos au lit + glace sur le ventre<br>\n              · <span><span class=\"nc-pink_bg\">Antalgiques</span></span> + <span><span class=\"nc-pink_bg\">AINS</span></span> (<span>CI si grossesse</span>)<br>\n              · Antibiotiques si surinfection suspectée\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Complications obstétricales et gravidiques</h4>\n\n      <p>Retentissement <em>global modéré</em> une fois la <span><span class=\"nc-pink_bg\">grossesse</span></span> installée, mais risque majoré de <strong><span><span class=\"nc-red\">hospitalisation</span></span>, <span class=\"nc-red\">césarienne</span>, complications du <span class=\"nc-pink_bg\">post-partum</span></strong>.</p>\n\n      <ul>\n        <li><strong><span class=\"nc-orange_bg\">Infertilité</span>, <span class=\"nc-orange_bg\">fausses couches spontanées</span></strong> : si <span class=\"nc-red nc-bold\">fibrome sous-muqueux déformant la cavité</span></li>\n        <li><strong><span><span class=\"nc-red_bg\">Menace</span></span><span class=\"nc-red_bg\"> d’accouchement prématuré / prématurité</span></strong> : si <span class=\"nc-red nc-bold\">nécrobiose aseptique</span> (plus fréquente en <span><span class=\"nc-pink_bg\">grossesse</span></span>)</li>\n        <li><strong><span class=\"nc-red_bg\">Localisation praevia</span></strong> gênant l’accouchement par voie basse</li>\n        <li><strong><span class=\"nc-red_bg\">Présentation dystocique</span></strong> si <span class=\"nc-red_bg\">fibrome volumineux</span> interstitiel</li>\n        <li><strong>Dystocie dynamique / <span class=\"nc-red_bg\">hémorragie de la délivrance</span></strong> : mauvaise rétraction utérine</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège.</strong> Devant <em><span>fièvre</span> + douleur pelvienne intense chez une femme enceinte connue pour un fibrome</em>, évoquer la <strong><span class=\"nc-red nc-bold\">nécrobiose aseptique</span></strong>. <span><span class=\"nc-pink_bg\">AINS</span> contre-indiqués pendant la <span class=\"nc-pink_bg\">grossesse</span></span> — <span><span class=\"nc-pink_bg\">antalgiques</span></span> de palier adapté + repos + glace.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 24 — Complications de la <span><span class=\"nc-green_bg\">grossesse</span></span> · 23 — <span class=\"nc-green_bg\">Grossesse</span> normale</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/rpc/\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Recommandations pour la pratique clinique</a></li></ul></details>","frequence":0,"liens":[{"href":"https://onclepaul.fr/wp-content/uploads/2011/07/N%C3%A9crobiose-fibrome-ut%C3%A9rin.pdf","label":"Onclepaul — Nécrobiose de fibrome utérin (PDF)"}]},{"id":"44-6","rang":"B","rubrique":"Étiologies","titre":"Connaître les étiologies des kystes ovarien","contenu":"<div class=\"notion-course\"><p>Deux grandes familles, qu’il faut absolument distinguer (cf. obj-7) car la conduite à tenir diffère.</p>\n\n      <table>\n        <thead>\n          <tr><th>Famille</th><th>Mécanisme / type</th><th>Exemples</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Kystes fonctionnels</strong><br><em>(les plus fréquents)</em></td>\n            <td>Anomalie d’un follicule au cours du cycle · <strong>régressent spontanément</strong></td>\n            <td>· <strong><span>Kyste folliculaire</span></strong> (follicule non rompu)<br>· <strong><span>Kyste lutéal</span></strong> (corps jaune persistant)</td>\n          </tr>\n          <tr>\n            <td rowspan=\"3\"><strong>Kystes organiques</strong><br><em>(persistants → <span>exérèse</span>)</em></td>\n            <td><strong>Épithéliaux</strong> (<span>~ 90 %</span> des organiques)</td>\n            <td><strong><span>Cystadénome séreux</span></strong>, <strong>mucineux</strong>, endométrioïde · tumeur de Brenner</td>\n          </tr>\n          <tr>\n            <td><strong>Germinaux</strong></td>\n            <td><strong><span>Tératome mature = <span class=\"nc-orange_bg\">kyste dermoïde</span></span></strong> (cheveux, dents, graisse)</td>\n          </tr>\n          <tr>\n            <td><strong>Endométriosique</strong></td>\n            <td><strong><span><span class=\"nc-orange_bg\">Endométriome</span></span></strong> (« kyste chocolat ») → rechercher une <span class=\"nc-red nc-bold\">endométriose</span> profonde associée</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> <em>Fonctionnel</em> = transitoire, <span>surveillance</span> écho à <span>3 mois</span>. <em>Organique</em> = persiste après <span>3 mois</span> → cœlioscopie (<span>kystectomie / annexectomie</span>). Toute zone <strong>solide / végétation</strong> fait craindre une tumeur <span>borderline ou maligne</span>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 306 — Tumeur de l’ovaire · 41 — Endométriose</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/rpc/\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Recommandations pour la pratique clinique</a></li></ul></details>","frequence":0},{"id":"44-7","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les symptômes et les éléments de l’examen clinique liés aux kystes ovariens","contenu":"<div class=\"notion-course\"><h4>Circonstances de découverte</h4>\n\n      <ul>\n        <li><strong>Le plus souvent asymptomatique</strong> → découverte <em>fortuite</em> (examen, <span>échographie</span>)</li>\n        <li><strong>Syndrome de <span>masse</span> pelvienne</strong> si volumineux : <span>pesanteur</span>, augmentation du volume abdominal, signes de compression (vésicale, digestive)</li>\n        <li><strong>Douleur pelvienne</strong> → fait évoquer une <span>complication</span> (torsion, hémorragie intra-kystique, <span>rupture</span> — cf. obj-8)</li>\n      </ul>\n\n      <h4>Examen clinique — toucher vaginal</h4>\n\n      <p>Le kyste ovarien donne classiquement une <strong><span>masse</span> latéro-utérine <span>indépendante</span> de l’utérus</strong> :</p>\n      <ul>\n        <li><strong>Séparée de l’utérus par un sillon</strong>, ne transmet pas les mouvements (main abdominale ↔ doigts vaginaux)</li>\n        <li><strong>Régulière et mobile</strong> → oriente vers un kyste bénin (ou un <span class=\"nc-orange_bg\">fibrome pédiculé</span>)</li>\n        <li><strong>Irrégulière et fixée</strong> → fait craindre un <span><span class=\"nc-red nc-bold\">cancer de l’ovaire</span></span>, une <span class=\"nc-red nc-bold\">endométriose</span> ou une cause infectieuse</li>\n      </ul>\n\n      <p>Compléter par l’<strong>examen abdominal</strong> (pôle supérieur si grande taille, recherche d’<span>ascite</span> / <span>hépatomégalie</span> → orientation maligne) et le <strong>toucher rectal</strong>.</p>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> <span><span class=\"nc-yellow_bg\">Masse</span></span><span class=\"nc-yellow_bg\"> </span><em><span class=\"nc-yellow_bg\">indépendante de l’utérus</span> + régulière + mobile</em> = profil bénin. Tout caractère <em>fixé, irrégulier, avec ascite</em> = <span>suspicion de malignité</span> → <span>échographie</span> puis <span><span class=\"nc-blue_bg\">IRM</span></span> + marqueurs.\n      </div></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/rpc/\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Recommandations pour la pratique clinique</a></li></ul></details>","frequence":0},{"id":"44-8","rang":"A","rubrique":"Étiologies","titre":"Savoir différencier kystes fonctionnel et organique","contenu":"<div class=\"notion-course\"><ul><li>Kyste fonctionnel : lié à l’activité ovarienne, souvent simple et régressif. Une image compatible peut être surveillée selon taille, symptômes et contexte hormonal.</li><li>Kyste organique : lésion persistante ou de nature tumorale, souvent bénigne ; persistance ne signifie pas cancer et n’impose pas à elle seule une chirurgie.</li><li>Échographie : morphologie, caractère uni-/multiloculaire, paroi, cloisons, végétations, composante solide, vascularisation, ascite et contexte ménopausique. Une taille ou un index Doppler isolé ne prouve pas la bénignité.</li><li>IRM en cas de caractérisation indéterminée. La surveillance ou l’intervention dépend de l’ensemble du dossier, du risque de complication et du projet reproductif.</li><li>Une masse suspecte nécessite orientation spécialisée ; éviter ponction ou rupture non planifiée. Les kystes bénins ne sont pas tous des lésions précancéreuses.</li></ul></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/rpc/\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Recommandations pour la pratique clinique</a></li></ul></details>","frequence":0},{"id":"44-9","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître les principales complications des kystes ovariens","contenu":"<div class=\"notion-course\"><p>Les complications d’un kyste ovarien sont des <strong>urgences douloureuses</strong> qu’il faut savoir évoquer devant une douleur pelvienne aiguë.</p>\n\n      <table>\n        <thead>\n          <tr><th>Complication</th><th>Caractéristiques</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span>Torsion d’annexe</span></strong></td>\n            <td>La plus grave — <span>urgence</span> chirurgicale (cf. obj-9) · risque de <strong><span>nécrose</span> ovarienne</strong> · favorisée par les kystes lourds (<span>dermoïde</span>)</td>\n          </tr>\n          <tr>\n            <td><strong><span>Hémorragie intra-kystique</span></strong></td>\n            <td>Douleur brutale · hyperdensité du contenu à l’imagerie · le plus souvent résolutive sous traitement médical</td>\n          </tr>\n          <tr>\n            <td><strong><span>Rupture de kyste</span></strong></td>\n            <td>Douleur brutale + <span>épanchement</span> du Douglas · risque d’<span>hémopéritoine</span> si <span>rupture</span> <span>hémorragique</span></td>\n          </tr>\n          <tr>\n            <td><strong>Abcédation / <span class=\"nc-red nc-bold\">infection</span></strong></td>\n            <td>Plus rare · contexte <span>infectieux</span> (<span><span class=\"nc-purple_bg\">abcès</span></span><span class=\"nc-purple_bg\"> ovarien</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Dégénérescence maligne</strong></td>\n            <td>Surtout les kystes <strong>organiques</strong> persistants · à craindre devant une zone solide / végétation</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Réflexe.</strong> Devant une <em>douleur pelvienne aiguë + <span>masse</span> annexielle</em>, penser en premier à la <span>torsion d’annexe</span> (cf. obj-9) — c’est la complication qui impose une <strong><span>chirurgie</span> en <span>urgence</span></strong> pour sauver l’ovaire.\n      </div></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/rpc/\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Recommandations pour la pratique clinique</a></li></ul></details>","frequence":0},{"id":"44-10","rang":"A","rubrique":"Identifier une urgence","titre":"Savoir évoquer une torsion d’annexe","contenu":"<div class=\"notion-course\"><ul><li>Torsion d’annexe : douleur pelvienne brutale, souvent unilatérale, parfois intermittente, avec nausées/vomissements ; masse annexielle ou contexte de stimulation ovarienne possibles mais non indispensables.</li><li>Test de <span class=\"nc-green_bg\">grossesse</span> et <span class=\"nc-blue_bg\">échographie pelvienne</span> Doppler, sans retarder l’avis gynécologique. Un flux Doppler conservé n’exclut pas une torsion.</li><li>Suspicion clinique forte : exploration chirurgicale urgente. Il n’existe pas de délai seuil de six heures permettant d’attendre en sécurité.</li><li>Détorsion et conservation ovarienne lorsque possible, notamment chez une patiente jeune ; un aspect sombre ne suffit pas à conclure à une destruction irréversible. Traitement de la lésion associée selon contexte et risque oncologique.</li></ul><figure class=\"obj-figure\">\n        <svg class=\"atlas-fig\" viewbox=\"0 0 560 130\" role=\"img\" aria-label=\"Frise de la conduite à tenir devant une suspicion de torsion d&#x27;annexe : douleur pelvienne brutale unilatérale, puis échographie pelvienne avec écho-Doppler — un Doppler normal n&#x27;élimine pas le diagnostic —, puis cœlioscopie en urgence en moins de 6 heures, et enfin détorsion conservatrice avec kystectomie.\" style=\"height:auto;display:block;border-radius:8px\">\n          <text class=\"tx-title\" x=\"280\" y=\"18\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"600\">Torsion d'annexe — urgence chirurgicale</text>\n          <rect class=\"fb-red\" x=\"8\" y=\"42\" width=\"125\" height=\"72\" rx=\"6\"></rect>\n          <text class=\"tx-red\" x=\"70.5\" y=\"66\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"600\">Douleur pelvienne</text>\n          <text class=\"tx-red\" x=\"70.5\" y=\"80\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"600\">brutale</text>\n          <text class=\"tx-red\" x=\"70.5\" y=\"98\" text-anchor=\"middle\" font-size=\"7.5\">unilatérale</text>\n          <rect class=\"fb-blue\" x=\"147\" y=\"42\" width=\"125\" height=\"72\" rx=\"6\"></rect>\n          <text class=\"tx-blue\" x=\"209.5\" y=\"66\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"600\"><span>Échographie</span> +</text>\n          <text class=\"tx-blue\" x=\"209.5\" y=\"80\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"600\"><span>écho-Doppler</span></text>\n          <text class=\"tx-blue\" x=\"209.5\" y=\"98\" text-anchor=\"middle\" font-size=\"7\">Doppler normal n'exclut pas</text>\n          <rect class=\"fb-red\" x=\"286\" y=\"42\" width=\"125\" height=\"72\" rx=\"6\"></rect>\n          <text class=\"tx-red\" x=\"348.5\" y=\"66\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"600\">Cœlioscopie</text>\n          <text class=\"tx-red\" x=\"348.5\" y=\"80\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"700\">&lt;<span> 6 h</span></text>\n          <text class=\"tx-red\" x=\"348.5\" y=\"98\" text-anchor=\"middle\" font-size=\"7.5\">urgence — ne pas retarder</text>\n          <rect class=\"fb-ok\" x=\"425\" y=\"42\" width=\"125\" height=\"72\" rx=\"6\"></rect>\n          <text class=\"tx-ok\" x=\"487.5\" y=\"66\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"600\">Détorsion</text>\n          <text class=\"tx-ok\" x=\"487.5\" y=\"80\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"600\">conservatrice</text>\n          <text class=\"tx-ok\" x=\"487.5\" y=\"98\" text-anchor=\"middle\" font-size=\"7.5\">+ kystectomie</text>\n          <line class=\"ln\" x1=\"135\" y1=\"78\" x2=\"144\" y2=\"78\" stroke-width=\"2\"></line>\n          <polygon class=\"ah\" points=\"147,78 141,74 141,82\"></polygon>\n          <line class=\"ln\" x1=\"274\" y1=\"78\" x2=\"283\" y2=\"78\" stroke-width=\"2\"></line>\n          <polygon class=\"ah\" points=\"286,78 280,74 280,82\"></polygon>\n          <line class=\"ln\" x1=\"413\" y1=\"78\" x2=\"422\" y2=\"78\" stroke-width=\"2\"></line>\n          <polygon class=\"ah\" points=\"425,78 419,74 419,82\"></polygon>\n        </svg>\n        <figcaption>La clinique prime : un écho-Doppler normal n’élimine pas le diagnostic — cœlioscopie en urgence &lt;<span> 6 h</span>, détorsion conservatrice (conserver l’ovaire même d’aspect nécrotique).</figcaption>\n      </figure></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/rpc/\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Recommandations pour la pratique clinique</a></li></ul></details>","frequence":0},{"id":"44-11","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les deux principaux examens radiologiques complémentaires à réaliser en cas de tuméfaction pelvienne et leur hiérarchisation (première et deuxième intention)","contenu":"<div class=\"notion-course\"><h4>Hiérarchisation EDN — <span class=\"nc-yellow_bg\">fibrome utérin</span></h4>\n      <table>\n        <thead>\n          <tr><th>Examen</th><th>Place</th><th>Description sémiologique</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span><span class=\"nc-blue_bg\">Échographie</span></span><span class=\"nc-blue_bg\"> pelvienne</span></strong></td>\n            <td><strong>1ʳᵉ intention</strong> — examen qui fait le diagnostic</td>\n            <td>\n              · Formations <strong>homogènes</strong>, <span>hypoéchogènes</span> par rapport au reste du myomètre<br>\n              · Généralement <strong>bien limitées</strong><br>\n              · <span>Encorbellement vasculaire</span> caractéristique<br>\n              · Nécrobiose : <span>image en « cocarde » avec hyperéchogénicité centrale</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span><span class=\"nc-blue_bg\">IRM</span></span> pelvienne</strong></td>\n            <td><strong>2ᵉ intention</strong></td>\n            <td>\n              Indications :<br>\n              · <span>Masse</span> <span><span class=\"nc-red nc-bold\">&gt; 10 cm</span></span><br>\n              · Nombre de <span class=\"nc-orange_bg\">fibromes</span> <span>&gt; 5</span><br>\n              · <span><span class=\"nc-red nc-bold\">Échographie</span></span><span class=\"nc-red nc-bold\"> insuffisante</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Bilan <span>biologique</span> d’accompagnement</h4>\n      <ul>\n        <li><strong><span>NFS</span> + <span>ferritine</span></strong> : rechercher une anémie ferriprive (complication des ménométrorragies)</li>\n        <li><strong>β-hCG</strong> systématique en âge de procréer avant toute exploration</li>\n        <li><span>Bilan préopératoire</span> si <span>chirurgie</span> envisagée</li>\n      </ul>\n\n      <h4>Hiérarchisation EDN — <span>masse</span> ovarienne</h4>\n      <table>\n        <thead>\n          <tr><th>Examen</th><th>Place</th><th>Apport</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span><span class=\"nc-blue_bg\">Échographie</span></span><span class=\"nc-blue_bg\"> pelvienne</span></strong><br>(sus-pubienne + endovaginale)</td>\n            <td><strong>1ʳᵉ intention</strong></td>\n            <td>Classe la <span>masse</span> : <strong>kyste fonctionnel</strong> <span>vs</span> <strong>organique</strong> <span>vs</span> <strong><span><span class=\"nc-orange_bg\">critères de</span></span><span class=\"nc-orange_bg\"> malignité</span></strong> · recherche d’<span>ascite</span></td>\n          </tr>\n          <tr>\n            <td><strong><span><span class=\"nc-blue_bg\">IRM</span></span> pelvienne</strong></td>\n            <td><strong>2ᵉ intention</strong></td>\n            <td><span class=\"nc-orange_bg\">Origine indéterminée</span> · <span><span class=\"nc-orange_bg\">critères de</span></span><span class=\"nc-orange_bg\"> malignité</span> · <strong><span><span class=\"nc-orange_bg\">masse</span></span><span class=\"nc-orange_bg\"> uniloculaire pure </span><span><span class=\"nc-orange_bg\">&gt; 7 cm</span></span></strong> (Se de l’écho moins bonne sur gros kyste)</td>\n          </tr>\n          <tr>\n            <td><strong><span>TDM</span> abdomino-pelvien</strong></td>\n            <td>Bilan d’extension</td>\n            <td>Si suspicion de <span>malignité</span> / carcinose (atteinte hépatique, <span>adénopathies</span>)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4><span class=\"nc-blue_bg\">Marqueurs tumoraux</span> (si <span>masse</span> suspecte)</h4>\n      <ul>\n        <li><strong><span><span class=\"nc-yellow_bg\">CA-125</span></span></strong> (± <span class=\"nc-yellow_bg\">HE4</span>, <span><span class=\"nc-yellow_bg\">ACE</span></span>, <span>CA 19-9</span>) : devant une tumeur ovarienne suspecte — <em>inutile sur un kyste manifestement bénin</em></li>\n        <li><strong><span><span class=\"nc-blue_bg\">LDH</span></span>, α-fœtoprotéine, <span class=\"nc-blue_bg\">hCG</span></strong> : si suspicion de <strong>tumeur germinale</strong> (femme jeune)</li>\n        <li><strong><span class=\"nc-pink_bg\">Estradiol</span>, AMH, <span class=\"nc-pink_bg\">inhibine B</span></strong> : si signes d’hyperœstrogénie / tumeur de la granulosa</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Synthèse 1ʳᵉ/2ᵉ intention.</strong> Quelle que soit la <span>tuméfaction</span> (utérine ou ovarienne) : <strong><span><span class=\"nc-blue_bg\">échographie pelvienne</span></span> en 1ʳᵉ intention</strong>, <strong><span><span class=\"nc-blue_bg\">IRM</span></span> en 2ᵉ intention</strong> sur les masses complexes / volumineuses / indéterminées. Précéder de la <span><span class=\"nc-pink nc-bold\">β-hCG</span></span> en âge de procréer.\n      </div></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/rpc/\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Recommandations pour la pratique clinique</a></li></ul></details>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/hysterosalpingogram","label":"Radiopaedia : Hystérosalpingographie (HSG)"}]},{"id":"44-12","rang":"A","rubrique":"Définition","titre":"Définir le prolapsus génital de la femme","contenu":"<div class=\"notion-course\"><p>Le <span>prolapsus génital</span> est une <strong>hernie des organes pelviens à travers le <span class=\"nc-yellow_bg nc-bold\">vagin</span></strong> — il s’<span class=\"nc-orange_bg\">extériorise</span> par <strong><span>tuméfaction vaginale</span></strong>, <em>non palpable au niveau abdominal</em>. C’est la différence fondamentale avec un fibrome ou une <span>masse</span> annexielle.</p>\n\n      <h4>Rappels anatomiques</h4>\n\n      <ul>\n        <li><strong>Pelvis</strong> : compartiment entre le <span class=\"nc-blue_bg\">détroit supérieur</span> et le plancher pelvien (muscle <em><span>levator ani</span></em>)</li>\n        <li><strong>Périnée</strong> : sous le plan du <span>levator ani</span> · orifices vulvaire et anal · <span class=\"nc-blue_bg\">fosses ischiorectales</span></li>\n        <li>Le pelvis contient d’avant en arrière : <strong>bas appareil urinaire</strong> (<span class=\"nc-purple_bg\">urètre</span>, <span class=\"nc-purple_bg\">vessie</span>) · <strong>appareil génital</strong> (<span class=\"nc-purple_bg\">ovaires</span>, <span class=\"nc-purple_bg\">trompes</span>, <span class=\"nc-purple_bg\">utérus</span>, <span class=\"nc-purple_bg\">vagin</span>) · <strong>appareil digestif</strong> (<span class=\"nc-purple_bg\">rectum</span>, <span class=\"nc-purple_bg\">canal anal</span>, ± sigmoïde, caecum)</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique.</strong> <em><span><span class=\"nc-blue_bg\">Rectocèle</span></span> ≠ prolapsus rectal</em>. La <span class=\"nc-blue_bg\">rectocèle</span> = <span class=\"nc-purple_bg\">rectum</span> qui bombe à travers le <span class=\"nc-purple_bg\">vagin</span>. Le prolapsus rectal = extériorisation du <span class=\"nc-purple_bg\">rectum</span> <strong>par l’anus</strong> (item HGE).\n      </div></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/rpc/\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Recommandations pour la pratique clinique</a></li></ul></details>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/pelvic-organ-prolapse","label":"Radiopaedia : Pelvic organ prolapse"}]},{"id":"44-13","rang":"B","rubrique":"Définition","titre":"Définir les différents compartiments du prolapsus","contenu":"<div class=\"notion-course\"><p>Deux nomenclatures coexistent (selon que l’on décrit la <em>paroi vaginale</em> qui descend ou <em>l’organe</em> qui bombe).</p>\n\n      <table>\n        <thead>\n          <tr><th>Étage</th><th>Paroi vaginale (colpocèle)</th><th>Organe extériorisé</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Antérieur</strong></td>\n            <td>Colpocèle antérieur (face antérieure du <span class=\"nc-yellow_bg nc-bold\">vagin</span>)</td>\n            <td><strong><span><span class=\"nc-blue_bg\">Cystocèle</span></span></strong> = <em><span class=\"nc-purple nc-bold\">vessie</span></em></td>\n          </tr>\n          <tr>\n            <td><strong>Moyen</strong></td>\n            <td>Colpocèle apical (apex du <span class=\"nc-yellow_bg nc-bold\">vagin</span>)</td>\n            <td><strong><span>Hystérocèle / hystéroptose</span></strong> = <em><span class=\"nc-purple nc-bold\">utérus</span></em></td>\n          </tr>\n          <tr>\n            <td rowspan=\"3\"><strong>Postérieur</strong></td>\n            <td rowspan=\"3\">Colpocèle postérieur (face postérieure du <span class=\"nc-yellow_bg nc-bold\">vagin</span>)</td>\n            <td><strong><span><span class=\"nc-blue_bg\">Rectocèle</span></span></strong> = <em><span class=\"nc-purple nc-bold\">rectum</span></em></td>\n          </tr>\n          <tr><td><strong><span><span class=\"nc-blue_bg\">Élytrocèle</span></span></strong> = <em>cul-de-sac recto-utérin (Douglas)</em></td></tr>\n          <tr><td><strong><span>Entérocèle</span></strong> = <em>intestin</em></td></tr>\n        </tbody>\n      </table></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/rpc/\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Recommandations pour la pratique clinique</a></li></ul></details>","frequence":1},{"id":"44-14","rang":"B","rubrique":"Diagnostic positif","titre":"Citer les diagnostics différentiels du prolapsus génital de la femme","contenu":"<div class=\"notion-course\"><p>Devant une <strong><span>tuméfaction vaginale</span> extériorisée</strong>, plusieurs diagnostics imitent le prolapsus. Le <span>TV</span>/TR et l’<span>échographie</span> aident à les écarter.</p>\n\n      <ul>\n        <li><strong><span><span class=\"nc-orange nc-bold\">Kyste vaginal</span></span></strong> (ex. kyste du canal de Gartner)</li>\n        <li><strong><span><span class=\"nc-orange nc-bold\">Fibrome de la cloison vésico-vaginale</span></span></strong> / fibrome accouché par le col</li>\n        <li><strong><span>Polype cervical extériorisé</span></strong></li>\n        <li><strong><span><span class=\"nc-red nc-bold\">Ascite</span></span></strong> : peut <em>provoquer ou aggraver</em> l’extériorisation d’un prolapsus</li>\n        <li><strong><span>Prolapsus rectal</span></strong> (extériorisation du <span class=\"nc-purple nc-bold\">rectum</span> <em>par l’anus</em> — à ne pas confondre avec une <span class=\"nc-blue_bg\">rectocèle</span>)</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Démarche.</strong> <span><span class=\"nc-blue_bg\">Échographie abdomino-pelvienne</span></span> souvent demandée pour <em>éliminer</em> un <span class=\"nc-orange nc-bold\">kyste vaginal</span>, un <span class=\"nc-orange nc-bold\">fibrome de la cloison vésico-vaginale</span> ou une <span class=\"nc-red nc-bold\">ascite</span>. Au <span>TV</span>/TR, le prolapsus <strong>ne contient pas de <span>masse</span></strong> propre — c’est un point distinctif.\n      </div></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/rpc/\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Recommandations pour la pratique clinique</a></li></ul></details>","frequence":0},{"id":"44-15","rang":"B","rubrique":"Epidémiologie","titre":"Connaître la fréquence du prolapsus","contenu":"<div class=\"notion-course\"><table>\n        <thead>\n          <tr><th>Âge</th><th><span>Prévalence</span></th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Jusqu’à<span> 50 ans</span></strong></td>\n            <td>Augmente avec l’âge : <span>3–11 %</span> au questionnaire <span>vs</span> <span>30–90 %</span> cliniquement</td>\n          </tr>\n          <tr>\n            <td><strong>Après <span>50 ans</span></strong></td>\n            <td><span>Prévalence</span> <strong>stable</strong>, mais le <strong><span><span class=\"nc-red nc-bold\">grade</span></span><span class=\"nc-red nc-bold\"> du prolapsus augmente</span></strong><span class=\"nc-red nc-bold\"> avec l’âge</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> L’écart majeur entre <span>prévalence</span> <em>au questionnaire</em> (<span>3–11 %</span>) et <em>clinique</em> (<span>30–90 %</span>) explique qu’un <strong>grand nombre de prolapsus sont asymptomatiques</strong>. Le traitement n’est proposé que <em>si la patiente est gênée</em>. <em>(FR détaillés dans l’onglet « Astuces PU &amp; Pièges ».)</em>\n      </div></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/rpc/\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Recommandations pour la pratique clinique</a></li></ul></details>","frequence":1},{"id":"44-16","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques du prolapsus","contenu":"<div class=\"notion-course\"><h4>Symptôme principal</h4>\n\n      <ul>\n        <li><strong><span><span class=\"nc-blue_bg\">Pesanteur pelvienne</span></span></strong> et <strong><span class=\"nc-blue_bg\">sensation de boule à la vulve</span></strong></li>\n        <li><strong>Augmentée à l’orthostatisme</strong> et <span class=\"nc-red nc-bold\">en </span><strong><span class=\"nc-red nc-bold\">fin de journée</span></strong></li>\n      </ul>\n\n      <h4>Signes fonctionnels associés</h4>\n\n      <table>\n        <thead>\n          <tr><th>Système</th><th>Manifestations</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Urinaires</strong></td>\n            <td>\n              · <span class=\"nc-orange_bg\">Syndrome d’</span><strong><span class=\"nc-orange_bg\">hyperactivité vésicale</span></strong> : <span>urgenturie</span>, IUU<br>\n              · Trouble de la <strong>vidange vésicale</strong> aux stades avancés : <span><span class=\"nc-blue_bg\">dysurie</span></span>, <span class=\"nc-blue_bg\">RPM</span>, <span><span class=\"nc-blue_bg\">infection urinaire</span></span><span class=\"nc-blue_bg\"> récidivante</span>, <span><span class=\"nc-blue_bg\">RAU</span></span><br>\n              · Manœuvres digitales de réintroduction parfois nécessaires pour la miction<br>\n              · Mécanisme : <em>plicature/compression de l’<span class=\"nc-purple_bg\">urètre</span> lors de l’extériorisation du prolapsus</em> = « <span class=\"nc-red nc-bold\">effet pelote</span> » (obstacle sous-vésical)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Digestifs</strong> (rectocèles)</td>\n            <td>\n              · <strong><span class=\"nc-blue_bg\">Faux besoins</span></strong><span class=\"nc-blue_bg\"> pouvant conduire à des épisodes d’incontinence</span> (<span>fécalome</span> = fausse <span>diarrhée</span>)<br>\n              · <strong><span><span class=\"nc-yellow_bg\">Dyschésie</span></span></strong><span class=\"nc-yellow_bg\"> (exonération difficile)</span> — manœuvres digitales parfois nécessaires\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Génito-sexuels</strong></td>\n            <td>\n              · <strong><span>Dyspareunie</span></strong><br>\n              · <span class=\"nc-blue_bg\">Sensation de </span><strong><span><span class=\"nc-blue_bg\">béance vulvaire</span></span></strong><span class=\"nc-blue_bg\"> conduisant à l’arrêt de l’activité sexuelle</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Signe négatif</strong></td>\n            <td>Le <span class=\"nc-green_bg\">prolapsus génital </span><em><span class=\"nc-green_bg\">n’est habituellement</span> <span class=\"nc-green_bg\">pas douloureux</span></em></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Examen clinique</h4>\n\n      <ul>\n        <li><strong>Examen gynécologique aux valves</strong> : détermine l’étage pelvien concerné</li>\n        <li><strong><span>TV</span> / TR</strong> : recherche des diagnostics différentiels — <em>pas de <span>masse</span></em> dans le prolapsus</li>\n        <li><strong>Rechercher une IUE masquée</strong> par le prolapsus :\n          <ul>\n            <li><em>Comment ?</em> <strong><span class=\"nc-blue nc-bold\">Test d’effort de poussée abdominale et de </span><span><span class=\"nc-blue nc-bold\">toux</span></span></strong> avec <strong>vessie pleine + prolapsus réduit</strong></li>\n            <li><em>Mécanisme</em> : IUE masquée par la plicature/compression de l’urètre par le prolapsus</li>\n          </ul>\n        </li>\n        <li><strong>Qualité de vie</strong> : questionnaire validé <strong><span>PFDI-20</span></strong> (Pelvic Floor Distress Inventory)</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège thérapeutique.</strong> Les SFU associés ne sont pas spécifiques du prolapsus. Il faut prévenir la patiente : la <span><span class=\"nc-pink nc-bold\">chirurgie</span></span> corrigera la sensation de boule vaginale mais <em>ne corrige pas toujours les SFU associés</em>, qui peuvent être indépendants.\n      </div></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/rpc/\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Recommandations pour la pratique clinique</a></li></ul></details>","frequence":1}],"astuces":[],"strategie":{"urgence":"<p><strong>Torsion d’annexe <span class=\"q\">— <span class=\"kw-alerte\">urgence</span> chirurgicale</span></strong></p><p><span class=\"kw-alerte\">Cœlioscopie en urgence &lt; 6 h</span> : <span class=\"kw-ttt\">détorsion conservatrice</span> + kystectomie (conserver l’ovaire même d’aspect nécrotique)</p><ul><li>Douleur pelvienne <span class=\"kw-clinique\">brutale</span> unilatérale + <span class=\"kw-clinique\">nausées / vomissements</span>, sur kyste connu (surtout <span class=\"kw-etio\">dermoïde</span>)</li><li><span class=\"kw-imagerie\">Écho-Doppler</span> : arrêt du flux du pédicule — un Doppler normal <strong>n’élimine pas</strong> le diagnostic (la clinique prime)</li></ul><p><strong>Hémorragie intra-kystique / <span class=\"kw-alerte\">rupture</span> de kyste</strong></p><p>Le plus souvent résolutif sous <span class=\"kw-ttt\">traitement médical</span> ; <span class=\"kw-ttt\">chirurgie</span> si instabilité / hémopéritoine</p><ul><li>Douleur <span class=\"kw-clinique\">brutale</span> ± <span class=\"kw-clinique\">épanchement du Douglas</span></li><li>Risque d’<span class=\"kw-alerte\">hémopéritoine</span> si <span class=\"kw-alerte\">rupture</span> <span class=\"kw-etio\">hémorragique</span></li></ul>","redflags":"<ul><li><span class=\"kw-clinique\">Masse</span> <span class=\"kw-alerte\">irrégulière, fixée</span> au toucher vaginal</li><li><span class=\"kw-clinique\">Masse</span> à <span class=\"kw-alerte\">progression rapide</span> (évoque un sarcome utérin)</li><li><span class=\"kw-clinique\">Ascite</span> associée</li><li>Survenue <span class=\"kw-alerte\">après la ménopause</span></li><li>Zone <span class=\"kw-radio\">solide / végétation</span> ou cloison épaisse à l’<span class=\"kw-imagerie\">échographie</span></li></ul>","principes":"<p>Traiter <strong>si symptomatique</strong> ou suspect ; <span class=\"kw-ttt\">abstention / surveillance</span> possible si bénin et asymptomatique.</p><p><strong>Fibrome utérin</strong></p><ul><li><span class=\"kw-ttt\">Abstention</span> si asymptomatique</li><li>Médical (saignements) : <span class=\"kw-ttt\">acide tranexamique</span>, <span class=\"kw-ttt\">AINS</span>, <span class=\"kw-ttt\">progestatifs</span>, <span class=\"kw-ttt\">DIU au lévonorgestrel</span> (hors sous-muqueux)</li><li><span class=\"kw-ttt\">Chirurgie</span> : <span class=\"kw-ttt\">myomectomie</span> (conservatrice) ou <span class=\"kw-ttt\">hystérectomie</span> ; <span class=\"kw-ttt\">embolisation</span> des artères utérines (pas sur sous-muqueux)</li></ul><p><strong>Kyste ovarien</strong></p><ul><li>Fonctionnel → <span class=\"kw-ttt\">surveillance</span>, contrôle <span class=\"kw-imagerie\">écho</span> à <span class=\"kw-chiffre\">3 mois</span></li><li>Organique (persiste &gt;<span class=\"kw-chiffre\"> 3 mois</span>) → <span class=\"kw-ttt\">exérèse cœlioscopique</span> (kystectomie / annexectomie)</li></ul><p><strong>Prolapsus génital <span class=\"q\">— uniquement si gênant</span></strong></p><ul><li><span class=\"kw-ttt\">Rééducation périnéale</span> (stades 1-2)</li><li><span class=\"kw-ttt\">Pessaire</span> (stades 2-4)</li><li><span class=\"kw-ttt\">Chirurgie</span> si échec : <span class=\"kw-ttt\">promontofixation</span> cœlioscopique ou voie vaginale</li><li>Correction des FR modifiables : <span class=\"kw-clinique\">toux</span>, <span class=\"kw-clinique\">constipation</span>, <span class=\"kw-etio\">obésité</span></li></ul>","suivi":"<p><strong>Kyste fonctionnel :</strong> <span class=\"kw-imagerie\">écho</span> de contrôle à <span class=\"kw-chiffre\">3 mois</span> (régression attendue ; persistance → organique).<br><strong>Fibrome :</strong> <span class=\"kw-clinique\">régression habituelle après la ménopause</span> ; surveiller l’<span class=\"kw-bio\">anémie ferriprive</span>.<br><strong>Prolapsus :</strong> <span class=\"kw-clinique\">évolution</span> vers l’<span class=\"kw-alerte\">aggravation</span> sans correction des FR ; prévenir que la <span class=\"kw-ttt\">chirurgie</span> ne corrige pas toujours les SFU.</p>"},"liensGlobaux":[{"href":"https://radiopaedia.org/articles/uterine-leiomyoma","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/figo-classification-system-foruterine-leiomyoma","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/hysterosalpingogram","label":"radiopaedia.org"},{"href":"https://onclepaul.fr/wp-content/uploads/2011/07/N%C3%A9crobiose-fibrome-ut%C3%A9rin.pdf","label":"onclepaul.fr"},{"href":"https://radiopaedia.org/articles/pelvic-organ-prolapse","label":"radiopaedia.org"},{"href":"https://cego-obgyn.fr/deuxieme-cycle/","label":"Collège CNGOF–CEGO · Référentiel, 6e édition 2024"},{"href":"https://cngof.fr/rpc/","label":"CNGOF · Recommandations pour la pratique clinique"}],"arbre":{"rootId":"entry","nodes":[{"id":"entry","kind":"decision","label":"Douleur aiguë ou mauvaise tolérance ?","detail":"<ul><li>Grossesse possible, symptômes compressifs et contexte ménopausique.</li></ul>","branches":[{"label":"Oui","to":"urgent"},{"label":"Non","to":"echo"}]},{"id":"urgent","kind":"urgent","label":"Torsion, hémorragie ou infection ?","detail":"<ul><li>Avis urgent ; Doppler normal n’exclut pas une torsion.</li></ul>","branches":[]},{"id":"echo","kind":"decision","label":"Échographie pelvienne en première intention","detail":"<ul><li>IRM si masse indéterminée/cartographie ; ne pas confondre imagerie et preuve histologique.</li></ul>","branches":[{"label":"Utérine/myome","to":"myome"},{"label":"Annexielle","to":"annexe"},{"label":"Autre origine","to":"autre"}]},{"id":"myome","kind":"finish","label":"Retentissement et projet de grossesse","detail":"<ul><li>Saignement, volume, douleur, localisation ; abstention possible si asymptomatique.</li></ul>","branches":[]},{"id":"annexe","kind":"decision","label":"Kyste fonctionnel, organique ou suspect ?","detail":"<ul><li>Morphologie, taille, âge et évolution.</li></ul>","branches":[{"label":"Bénin présumé","to":"benin"},{"label":"Suspect/indéterminé","to":"suspect"}]},{"id":"benin","kind":"finish","label":"Surveillance ou intervention adaptée","detail":"<ul><li>Contrôle selon type et contexte ; consignes de torsion/rupture.</li></ul>","branches":[]},{"id":"suspect","kind":"finish","label":"Avis spécialisé et bilan adapté","detail":"<ul><li>Éviter ponction/rupture d’une masse suspecte ; centre expert si cancer possible.</li></ul>","branches":[]},{"id":"autre","kind":"finish","label":"Rechercher origine digestive/urinaire ou prolapsus","detail":"<ul><li>Examen et imagerie guidés par les signes.</li></ul>","branches":[]}]},"cards":[{"i":"86f530d01eda","n":44,"o":"44-1","u":"Étiologies","t":"Connaître les 2 étiologies les plus fréquentes de tuméfaction pelvienne","q":"Quel est un repère clinique clé permettant d'orienter le diagnostic vers un fibrome utérin lors de l'examen clinique d'une tuméfaction pelvienne ?","a":"<div class=\"notion-course\"><p>Un repère clinique clé pour le <strong><span class=\"nc-yellow_bg\">fibrome utérin</span></strong> est la palpation d'une <strong><span class=\"nc-yellow_bg\">masse dépendante de l'utérus</span></strong> au toucher vaginal.</p></div>"},{"i":"960532912607","n":44,"o":"44-1","u":"Étiologies","t":"Connaître les 2 étiologies les plus fréquentes de tuméfaction pelvienne","q":"Comment différencier cliniquement un utérus gravide d'autres tuméfactions pelviennes chez une femme en âge de procréer ?","a":"<div class=\"notion-course\"><p>Un <strong><span class=\"nc-green_bg\">utérus gravide</span></strong> sera généralement <strong>augmenté de volume et mou</strong>, le tout dans un contexte de <strong>retard de règles</strong>.</p></div>"},{"i":"97d43dd4e710","n":44,"o":"44-1","u":"Étiologies","t":"Connaître les 2 étiologies les plus fréquentes de tuméfaction pelvienne","q":"Quelle est la première étiologie à éliminer systématiquement devant toute tuméfaction pelvienne chez une femme en âge de procréer ?","a":"<div class=\"notion-course\"><p>Devant toute tuméfaction pelvienne chez une femme en âge de procréer, il faut systématiquement éliminer le diagnostic de <strong>grossesse</strong>. Cela se fait par le dosage des <strong><span class=\"nc-pink nc-bold\">β-hCG</span></strong>.</p></div>"},{"i":"a340a64fd761","n":44,"o":"44-1","u":"Étiologies","t":"Connaître les 2 étiologies les plus fréquentes de tuméfaction pelvienne","q":"Quelles sont les 2 étiologies les plus fréquentes de tuméfaction pelvienne chez une femme en âge de procréer, après avoir éliminé une grossesse ?","a":"<div class=\"notion-course\"><p>Après avoir éliminé une grossesse, les 2 étiologies les plus fréquentes de tuméfaction pelvienne sont :</p><ul><li>Le <strong><span class=\"nc-yellow_bg\">fibrome utérin</span></strong> (d'origine utérine).</li><li>Le <strong><span class=\"nc-orange_bg\">kyste de l'ovaire</span></strong> (d'origine ovarienne).</li></ul></div>"},{"i":"b26bbc72892e","n":44,"o":"44-1","u":"Étiologies","t":"Connaître les 2 étiologies les plus fréquentes de tuméfaction pelvienne","q":"Quel est un repère clinique clé permettant d'orienter le diagnostic vers un kyste de l'ovaire lors de l'examen clinique d'une tuméfaction pelvienne ?","a":"<div class=\"notion-course\"><p>Un repère clinique clé pour le <strong><span class=\"nc-orange_bg\">kyste de l'ovaire</span></strong> est la palpation d'une <strong>masse latéro-utérine indépendante de l'utérus</strong>.</p></div>"},{"i":"0093371e287d","n":44,"o":"44-10","u":"Identifier une urgence","t":"Savoir évoquer une torsion d’annexe","q":"Quelle est la prise en charge chirurgicale d'une torsion d'annexe ?","a":"<div class=\"notion-course\"><ul><li>Torsion d’annexe : douleur pelvienne brutale, souvent unilatérale, parfois intermittente, avec nausées/vomissements ; masse annexielle ou contexte de stimulation ovarienne possibles mais non indispensables.</li><li>Test de <span class=\"nc-green_bg\">grossesse</span> et <span class=\"nc-blue_bg\">échographie pelvienne</span> Doppler, sans retarder l’avis gynécologique. Un flux Doppler conservé n’exclut pas une torsion.</li><li>Suspicion clinique forte : exploration chirurgicale urgente. Il n’existe pas de délai seuil de six heures permettant d’attendre en sécurité.</li><li>Détorsion et conservation ovarienne lorsque possible, notamment chez une patiente jeune ; un aspect sombre ne suffit pas à conclure à une destruction irréversible. Traitement de la lésion associée selon contexte et risque oncologique.</li></ul></div>"},{"i":"5c1cb6fcfb16","n":44,"o":"44-10","u":"Identifier une urgence","t":"Savoir évoquer une torsion d’annexe","q":"Quelle est la stratégie diagnostique en cas de suspicion de torsion d'annexe et quelle est la place de l'échographie-Doppler ?","a":"<div class=\"notion-course\"><ul><li>Torsion d’annexe : douleur pelvienne brutale, souvent unilatérale, parfois intermittente, avec nausées/vomissements ; masse annexielle ou contexte de stimulation ovarienne possibles mais non indispensables.</li><li>Test de <span class=\"nc-green_bg\">grossesse</span> et <span class=\"nc-blue_bg\">échographie pelvienne</span> Doppler, sans retarder l’avis gynécologique. Un flux Doppler conservé n’exclut pas une torsion.</li><li>Suspicion clinique forte : exploration chirurgicale urgente. Il n’existe pas de délai seuil de six heures permettant d’attendre en sécurité.</li><li>Détorsion et conservation ovarienne lorsque possible, notamment chez une patiente jeune ; un aspect sombre ne suffit pas à conclure à une destruction irréversible. Traitement de la lésion associée selon contexte et risque oncologique.</li></ul></div>"},{"i":"826bc47a7858","n":44,"o":"44-10","u":"Identifier une urgence","t":"Savoir évoquer une torsion d’annexe","q":"Comment définir et caractériser la gravité de la torsion d'annexe ?","a":"<div class=\"notion-course\"><ul><li>Torsion d’annexe : douleur pelvienne brutale, souvent unilatérale, parfois intermittente, avec nausées/vomissements ; masse annexielle ou contexte de stimulation ovarienne possibles mais non indispensables.</li><li>Test de <span class=\"nc-green_bg\">grossesse</span> et <span class=\"nc-blue_bg\">échographie pelvienne</span> Doppler, sans retarder l’avis gynécologique. Un flux Doppler conservé n’exclut pas une torsion.</li><li>Suspicion clinique forte : exploration chirurgicale urgente. Il n’existe pas de délai seuil de six heures permettant d’attendre en sécurité.</li><li>Détorsion et conservation ovarienne lorsque possible, notamment chez une patiente jeune ; un aspect sombre ne suffit pas à conclure à une destruction irréversible. Traitement de la lésion associée selon contexte et risque oncologique.</li></ul></div>"},{"i":"a12f4bbece93","n":44,"o":"44-10","u":"Identifier une urgence","t":"Savoir évoquer une torsion d’annexe","q":"Quels signes cliniques doivent faire évoquer une torsion d'annexe ?","a":"<div class=\"notion-course\"><ul><li>Torsion d’annexe : douleur pelvienne brutale, souvent unilatérale, parfois intermittente, avec nausées/vomissements ; masse annexielle ou contexte de stimulation ovarienne possibles mais non indispensables.</li><li>Test de <span class=\"nc-green_bg\">grossesse</span> et <span class=\"nc-blue_bg\">échographie pelvienne</span> Doppler, sans retarder l’avis gynécologique. Un flux Doppler conservé n’exclut pas une torsion.</li><li>Suspicion clinique forte : exploration chirurgicale urgente. Il n’existe pas de délai seuil de six heures permettant d’attendre en sécurité.</li><li>Détorsion et conservation ovarienne lorsque possible, notamment chez une patiente jeune ; un aspect sombre ne suffit pas à conclure à une destruction irréversible. Traitement de la lésion associée selon contexte et risque oncologique.</li></ul></div>"},{"i":"4442d9c51e4c","n":44,"o":"44-12","u":"Définition","t":"Définir le prolapsus génital de la femme","q":"Quelle est la différence entre une rectocèle et un prolapsus rectal ?","a":"<div class=\"notion-course\"><p>Une <strong><span class=\"nc-blue_bg\">rectocèle</span></strong> est le bombement du <span class=\"nc-purple nc-bold\">rectum</span> à travers le <span class=\"nc-yellow_bg nc-bold\">vagin</span>. Un <strong>prolapsus rectal</strong> correspond à l'extériorisation du <span class=\"nc-purple nc-bold\">rectum</span> par l'anus.</p></div>"},{"i":"4a983152ecc6","n":44,"o":"44-12","u":"Définition","t":"Définir le prolapsus génital de la femme","q":"Quelle est la définition du prolapsus génital de la femme ?","a":"<div class=\"notion-course\"><p>Le prolapsus génital est une <strong>hernie des organes pelviens</strong> à travers le <span class=\"nc-yellow_bg nc-bold\">vagin</span>, s'extériorisant par une <strong>tuméfaction vaginale</strong>.</p></div>"},{"i":"776a975d87d1","n":44,"o":"44-12","u":"Définition","t":"Définir le prolapsus génital de la femme","q":"Comment différencier un prolapsus génital d'une masse abdominale ?","a":"<div class=\"notion-course\"><p>Le prolapsus génital se manifeste par une tuméfaction vaginale et n'est <strong>pas palpable</strong> au niveau abdominal, contrairement par exemple à un <span class=\"nc-yellow_bg\">fibrome utérin</span> ou une masse annexielle.</p></div>"},{"i":"4402adf598c8","n":44,"o":"44-16","u":"Diagnostic positif","t":"Connaître les signes cliniques du prolapsus","q":"Le prolapsus génital est-il habituellement douloureux ?","a":"<div class=\"notion-course\"><p>Non, le <span class=\"nc-green_bg\">prolapsus génital n’est </span><strong><span class=\"nc-green_bg\">habituellement</span> <span class=\"nc-green_bg\">pas douloureux</span></strong>. La douleur est un signe négatif à éliminer dans le diagnostic du prolapsus.</p></div>"},{"i":"4990e5dbbe64","n":44,"o":"44-16","u":"Diagnostic positif","t":"Connaître les signes cliniques du prolapsus","q":"Quels sont les signes fonctionnels digestifs et génito-sexuels pouvant être associés à un prolapsus génital ?","a":"<div class=\"notion-course\"><p>Les signes fonctionnels associés au prolapsus génital sont :</p><ul><li><strong>Digestifs (en cas de rectocèle)</strong> : faux besoins (pouvant entraîner une fausse diarrhée sur fécalome) et <strong><span class=\"nc-yellow_bg\">dyschésie</span></strong><span class=\"nc-yellow_bg\"> (exonération difficile)</span>, nécessitant parfois des manœuvres digitales.</li><li><strong>Génito-sexuels</strong> : <strong>dyspareunie</strong> et sensation de <strong>béance vulvaire</strong>, pouvant conduire à l’arrêt de l’activité sexuelle.</li></ul></div>"},{"i":"6b40131ccc4a","n":44,"o":"44-16","u":"Diagnostic positif","t":"Connaître les signes cliniques du prolapsus","q":"Quelles sont les manifestations urinaires pouvant être associées à un prolapsus génital ?","a":"<div class=\"notion-course\"><p>Les manifestations urinaires associées à un prolapsus peuvent inclure :</p><ul><li>Un <strong><span class=\"nc-orange_bg\">syndrome d’hyperactivité vésicale</span></strong> (urgenturie, incontinence urinaire par urgence).</li><li>Des <strong>troubles de la vidange vésicale</strong> aux stades avancés (<span class=\"nc-blue_bg\">dysurie</span>, résidu post-mictionnel, infections urinaires récidivantes, rétention aiguë d'urine), parfois nécessitant des manœuvres digitales de réintroduction.</li></ul><p>Ces troubles peuvent être liés à l'« <strong><span class=\"nc-red nc-bold\">effet pelote</span></strong> », une plicature ou compression de l'urètre lors de l'extériorisation du prolapsus, créant un obstacle sous-vésical.</p></div>"},{"i":"83c56f3582e2","n":44,"o":"44-16","u":"Diagnostic positif","t":"Connaître les signes cliniques du prolapsus","q":"Quel est le symptôme principal du prolapsus génital ?","a":"<div class=\"notion-course\"><p>Le symptôme principal du prolapsus génital est une <strong><span class=\"nc-blue_bg\">pesanteur pelvienne</span></strong> et une <strong><span class=\"nc-blue_bg\">sensation de boule à la vulve</span></strong>. Ces symptômes sont augmentés à l’orthostatisme et <span class=\"nc-red nc-bold\">en fin de journée</span>.</p></div>"},{"i":"a5232121b5ec","n":44,"o":"44-16","u":"Diagnostic positif","t":"Connaître les signes cliniques du prolapsus","q":"Comment rechercher une incontinence urinaire à l'effort (IUE) masquée lors de l'examen clinique d'un prolapsus ?","a":"<div class=\"notion-course\"><p>Pour rechercher une IUE masquée par le prolapsus, il faut réaliser un <strong><span class=\"nc-blue nc-bold\">test d’effort de poussée abdominale et de toux</span></strong> avec la <strong>vessie pleine</strong>, après avoir <strong>réduit le prolapsus</strong>. L'IUE peut être masquée par la plicature ou la compression de l'<span class=\"nc-purple_bg\">urètre</span> par le prolapsus lui-même.</p></div>"},{"i":"5cddeadf5bb1","n":44,"o":"44-2","u":"Étiologies","t":"Connaître les autres causes de tuméfaction pelvienne","q":"Outre la grossesse, le fibrome et le kyste ovarien, quelles sont les causes utérines de tuméfaction pelvienne chez la femme ?","a":"<div class=\"notion-course\">Les causes utérines incluent :\n<ul>\n<li>Le <strong><span class=\"nc-red_bg\">sarcome</span> utérin</strong> / <strong>léiomyosarcome</strong> : rare, souvent après la ménopause, avec une masse à <span class=\"nc-red nc-bold\">progression rapide</span>.</li>\n<li>L'<strong><span class=\"nc-brown_bg\">adénomyose</span></strong> : <span class=\"nc-brown_bg\">rarement</span>, l'utérus ne dépasse généralement pas deux fois sa taille normale.</li>\n<li>Le <strong>cancer de l'endomètre</strong> : exceptionnellement, surtout si la tumeur est endocavitaire avec sténose du col, entraînant alors une <span class=\"nc-blue nc-bold\">hématométrie</span> ± <span class=\"nc-blue nc-bold\">pyométrie</span>.</li>\n</ul></div>"},{"i":"7e1ab343f861","n":44,"o":"44-2","u":"Étiologies","t":"Connaître les autres causes de tuméfaction pelvienne","q":"Outre la grossesse, le fibrome et le kyste ovarien, quelles sont les causes péritonéales et digestives pouvant provoquer une tuméfaction pelvienne chez la femme ?","a":"<div class=\"notion-course\">Les causes péritonéales et digestives incluent :\n<ul>\n<li><strong>Péritonéales</strong> : L'<strong><span class=\"nc-orange_bg\">endométriose du cul-de-sac recto-utérin</span></strong>, qui se présente plus comme une <span class=\"nc-blue nc-bold\">induration</span> ou un <span class=\"nc-blue nc-bold\">nodule</span> qu'une véritable masse.</li>\n<li><strong>Digestives</strong> (rares) :\n<ul>\n<li>La <strong>sigmoïdite</strong>.</li>\n<li>Le <strong>cancer colorectal</strong>.</li>\n</ul>\n</li>\n</ul></div>"},{"i":"86adaa8aef0f","n":44,"o":"44-2","u":"Étiologies","t":"Connaître les autres causes de tuméfaction pelvienne","q":"Outre la grossesse, le fibrome et le kyste ovarien, quelles sont les causes ovariennes et tubaires de tuméfaction pelvienne chez la femme ?","a":"<div class=\"notion-course\">Les causes ovariennes et tubaires incluent :\n<ul>\n<li><strong>Ovariennes</strong> :\n<ul>\n<li>L'<strong><span class=\"nc-purple_bg\">abcès ovarien</span></strong> (post-pelvipéritonite, post-ponction).</li>\n<li>L'<strong>endométriome</strong>.</li>\n<li>Le <strong><span class=\"nc-orange_bg\">cancer de l'ovaire</span></strong> (rare avant la ménopause).</li>\n</ul>\n</li>\n<li><strong>Tubaires</strong> :\n<ul>\n<li>L'<strong>hydrosalpinx</strong>.</li>\n<li>Le <strong><span class=\"nc-orange_bg\">bloc adhérentiel post-infectieux</span></strong>.</li>\n<li>Le <strong>kyste paratubaire / vestigial</strong> (la trompe se dilate <span class=\"nc-brown_bg\">rarement</span> assez pour donner une masse importante, souvent masse annexielle infectieuse mixte trompe + ovaire).</li>\n</ul>\n</li>\n</ul></div>"},{"i":"c55083e4c5e1","n":44,"o":"44-2","u":"Étiologies","t":"Connaître les autres causes de tuméfaction pelvienne","q":"Quels sont les signes d'alerte (\"drapeau rouge\") pour envisager une tumeur maligne face à une tuméfaction pelvienne chez la femme ?","a":"<div class=\"notion-course\">Une masse pelvienne doit faire suspecter une tumeur maligne jusqu'à preuve du contraire si elle présente les caractéristiques suivantes :\n<ul>\n<li><strong>Irrégulière</strong>.</li>\n<li><strong>Fixée</strong>.</li>\n<li>À <strong><span class=\"nc-red nc-bold\">progression rapide</span></strong>.</li>\n<li>Surtout si elle survient <strong>après la ménopause</strong>.</li>\n<li>Ou en présence d'une <strong>ascite</strong>.</li>\n</ul>\nCela évoque particulièrement un cancer de l'ovaire, un sarcome ou un cancer de l'endomètre.</div>"},{"i":"0e9bf4dd0dd2","n":44,"o":"44-4","u":"Diagnostic positif","t":"Connaître les symptômes et les éléments de l’examen clinique liés aux fibromes","q":"Quelles sont les manifestations et les complications du syndrome de masse pelvienne associé aux fibromes utérins ?","a":"<div class=\"notion-course\"><p>Le <span class=\"nc-blue nc-bold\">syndrome de masse pelvienne</span> se caractérise par une <strong>pesanteur pelvienne</strong>, une <span class=\"nc-blue_bg\">masse abdominale</span> palpable et une <span class=\"nc-blue_bg\">augmentation du volume de l'abdomen</span>, d'apparition progressive et sans douleur vraie. Les complications résultent de la compression d'organes de voisinage :</p><ul><li><strong>Vésicales</strong> : pollakiurie, <span class=\"nc-orange_bg\">rétention d'urines</span>.</li><li><strong>Urétrale</strong> : <span class=\"nc-blue_bg\">urétéro-hydronéphrose</span>, <span class=\"nc-orange_bg\">coliques néphrétiques</span>, <span class=\"nc-orange_bg\">pyélonéphrites</span>.</li><li><strong>Digestives</strong> : <span class=\"nc-blue_bg\">constipation</span>, faux besoins.</li><li><strong>Veineuses pelviennes</strong> : <span class=\"nc-blue_bg\">œdèmes des membres inférieurs</span>, <span class=\"nc-orange_bg\">TVP</span>.</li><li><strong>Nerveuses</strong> : <span class=\"nc-orange_bg\">sciatalgie</span>, <span class=\"nc-orange_bg\">névralgie obturatrice</span>.</li></ul><p>Les <span class=\"nc-orange_bg\">fibromes</span> à risque de causer un <span class=\"nc-blue nc-bold\">syndrome de masse pelvienne</span> sont ceux de <strong>grand volume (&gt; 5 cm)</strong> et les <strong><span class=\"nc-orange_bg\">fibromes</span> <span class=\"nc-orange_bg nc-bold\">sous-séreux</span></strong> (FIGO 5-7).</p></div>"},{"i":"1cb65f4d0961","n":44,"o":"44-4","u":"Diagnostic positif","t":"Connaître les symptômes et les éléments de l’examen clinique liés aux fibromes","q":"Dans quel contexte clinique les dysménorrhées peuvent-elles être associées à des fibromes utérins ?","a":"<div class=\"notion-course\"><p>Les dysménorrhées peuvent être associées à des <span class=\"nc-orange_bg\">fibromes utérins</span> si le fibrome est situé au niveau du <strong>col</strong> ou de l'<strong>isthme</strong> (FIGO 8), car il peut gêner l'évacuation normale du flux menstruel.</p></div>"},{"i":"87c438d828fc","n":44,"o":"44-4","u":"Diagnostic positif","t":"Connaître les symptômes et les éléments de l’examen clinique liés aux fibromes","q":"Quels sont les éléments clés de l'examen clinique au toucher vaginal (TV) en présence de fibromes utérins ?","a":"<div class=\"notion-course\"><p>Lors du toucher vaginal (TV), les éléments clés sont :</p><ul><li>Des <strong><span class=\"nc-orange_bg\">fibromes</span> palpables</strong> (souvent <span class=\"nc-brown_bg\">interstitiels</span> ou <span class=\"nc-brown_bg\">sous-séreux</span>).</li><li>Un <strong>utérus augmenté de volume</strong>, en cas de <span class=\"nc-orange_bg\">fibromes interstitiels ou sous-séreux</span>.</li><li>Une <strong>masse latéro-utérine dépendante de l'utérus</strong> pour un <span class=\"nc-orange_bg\">fibrome sous-séreux sessile</span>.</li><li>Une <strong>masse latéro-utérine indépendante</strong>, évoquant un <span class=\"nc-orange_bg\">fibrome pédiculé</span>.</li></ul></div>"},{"i":"9c7588d339a5","n":44,"o":"44-4","u":"Diagnostic positif","t":"Connaître les symptômes et les éléments de l’examen clinique liés aux fibromes","q":"Quels sont les principaux tableaux cliniques des fibromes utérins symptomatiques ?","a":"<div class=\"notion-course\"><p>Les <span class=\"nc-orange_bg\">fibromes utérins</span> symptomatiques se manifestent principalement sous <strong>trois tableaux cliniques</strong> :</p><ul><li>Des <strong>saignements utérins anormaux</strong> (le signe le plus fréquent).</li><li>Un <strong><span class=\"nc-blue nc-bold\">syndrome de masse pelvienne</span></strong>.</li><li>Des <strong>dysménorrhées</strong>.</li></ul></div>"},{"i":"edb5d4e12464","n":44,"o":"44-4","u":"Diagnostic positif","t":"Connaître les symptômes et les éléments de l’examen clinique liés aux fibromes","q":"Comment les saignements utérins anormaux liés aux fibromes utérins se manifestent-ils et quels fibromes sont le plus souvent en cause ?","a":"<div class=\"notion-course\"><p>Les saignements utérins anormaux se manifestent par :</p><ul><li>Des <strong><span class=\"nc-yellow_bg\">ménorragies</span></strong> (règles <span class=\"nc-pink nc-bold\">&gt; 6 jours</span> et/ou <span class=\"nc-pink nc-bold\">&gt; 80 mL</span>), souvent associées à une polyménorrhée.</li><li>Des <strong>métrorragies</strong> sont rares isolées, mais des <strong>ménométrorragies</strong> sont plus fréquentes.</li></ul><p>Une complication fréquente est l'<strong><span class=\"nc-red nc-bold\">anémie ferriprive</span></strong>. Les <span class=\"nc-orange_bg\">fibromes</span> expliquant <span class=\"nc-red nc-bold\">le plus souvent</span> ces saignements sont les <strong><span class=\"nc-orange_bg\">fibromes</span> sous-muqueux</strong> (FIGO 0-2), suivis plus <span class=\"nc-brown_bg\">rarement</span> par les <span class=\"nc-orange_bg\">fibromes</span> <span class=\"nc-brown_bg\">interstitiels</span> (FIGO 3-4).</p></div>"},{"i":"f66a4149b8ba","n":44,"o":"44-4","u":"Diagnostic positif","t":"Connaître les symptômes et les éléments de l’examen clinique liés aux fibromes","q":"Quelle conduite à tenir est préconisée devant des ménométrorragies associées à un utérus polymyomateux palpable au TV ?","a":"<div class=\"notion-course\"><p>Devant des ménométrorragies et un utérus polymyomateux palpable au TV, il convient de :</p><ul><li>Doser la <strong>NFS et la ferritine</strong> (pour rechercher une <span class=\"nc-red nc-bold\">anémie ferriprive</span>).</li><li>Réaliser une <strong><span class=\"nc-blue_bg\">échographie pelvienne</span></strong>.</li><li>Apprécier le <strong>score de Higham</strong> pour quantifier les <span class=\"nc-yellow_bg\">ménorragies</span>.</li></ul></div>"},{"i":"29ac962ba208","n":44,"o":"44-7","u":"Diagnostic positif","t":"Connaître les symptômes et les éléments de l’examen clinique liés aux kystes ovariens","q":"Quelles sont les caractéristiques d'un kyste ovarien à l'examen clinique qui doivent faire craindre une malignité ou d'autres pathologies graves ?","a":"<div class=\"notion-course\"><p>Les caractéristiques d'un kyste ovarien devant faire craindre une <strong>malignité</strong> (cancer de l'ovaire) ou d'autres pathologies graves (<span class=\"nc-red nc-bold\">endométriose</span>, cause infectieuse) à l'examen clinique sont :</p><ul><li>Une masse <strong>irrégulière</strong>.</li><li>Une masse <strong>fixée</strong>.</li><li>La présence d'une <strong>ascite</strong> ou d'une <strong>hépatomégalie</strong> (recherchées lors de l'examen abdominal).</li></ul></div>"},{"i":"662021e267c4","n":44,"o":"44-7","u":"Diagnostic positif","t":"Connaître les symptômes et les éléments de l’examen clinique liés aux kystes ovariens","q":"Quels symptômes un kyste ovarien volumineux peut-il entraîner ?","a":"<div class=\"notion-course\"><p>Un kyste ovarien volumineux peut entraîner ce qu'on appelle un <strong>syndrome de masse pelvienne</strong>, se manifestant par :</p><ul><li>Une sensation de <strong>pesanteur</strong> pelvienne.</li><li>Une <strong>augmentation du volume abdominal</strong>.</li><li>Des <strong>signes de compression</strong>, notamment vésicale (miction fréquente) ou digestive (constipation).</li></ul></div>"},{"i":"6efe0b5461d9","n":44,"o":"44-7","u":"Diagnostic positif","t":"Connaître les symptômes et les éléments de l’examen clinique liés aux kystes ovariens","q":"Que doit faire évoquer une douleur pelvienne chez une patiente présentant un kyste ovarien ?","a":"<div class=\"notion-course\"><p>Une douleur pelvienne, en présence d'un kyste ovarien, doit faire évoquer une <strong>complication</strong> du kyste, telle qu'une <strong>torsion</strong> de l'ovaire, une <strong>hémorragie intra-kystique</strong> ou une <strong>rupture</strong> du kyste.</p></div>"},{"i":"79e8a6cba2b6","n":44,"o":"44-7","u":"Diagnostic positif","t":"Connaître les symptômes et les éléments de l’examen clinique liés aux kystes ovariens","q":"Dans quelles circonstances un kyste ovarien est-il le plus fréquemment découvert ?","a":"<div class=\"notion-course\"><p>La découverte d'un kyste ovarien est le plus souvent <strong>fortuite</strong>, lors d'un examen clinique de routine ou d'une échographie abdomino-pelvienne.</p></div>"},{"i":"f15fff7a775c","n":44,"o":"44-7","u":"Diagnostic positif","t":"Connaître les symptômes et les éléments de l’examen clinique liés aux kystes ovariens","q":"Quelles sont les caractéristiques principales d'un kyste ovarien bénin à l'examen clinique au toucher vaginal ?","a":"<div class=\"notion-course\"><p>À l'examen clinique, un kyste ovarien orientant vers la bénignité se présente classiquement comme une <strong>masse latéro-utérine</strong> qui est :</p><ul><li><strong>Indépendante de l'utérus</strong>, séparée par un sillon, et ne transmettant pas les mouvements utérins.</li><li>De consistance <strong>régulière</strong>.</li><li><strong>Mobile</strong>.</li></ul></div>"},{"i":"4ac3c6aa43d1","n":44,"o":"44-8","u":"Étiologies","t":"Savoir différencier kystes fonctionnel et organique","q":"Quelle est la conduite à tenir si un kyste ovarien présente des critères de malignité ou une zone solide à l'échographie ?","a":"<div class=\"notion-course\"><ul><li>Kyste fonctionnel : lié à l’activité ovarienne, souvent simple et régressif. Une image compatible peut être surveillée selon taille, symptômes et contexte hormonal.</li><li>Kyste organique : lésion persistante ou de nature tumorale, souvent bénigne ; persistance ne signifie pas cancer et n’impose pas à elle seule une chirurgie.</li><li>Échographie : morphologie, caractère uni-/multiloculaire, paroi, cloisons, végétations, composante solide, vascularisation, ascite et contexte ménopausique. Une taille ou un index Doppler isolé ne prouve pas la bénignité.</li><li>IRM en cas de caractérisation indéterminée. La surveillance ou l’intervention dépend de l’ensemble du dossier, du risque de complication et du projet reproductif.</li><li>Une masse suspecte nécessite orientation spécialisée ; éviter ponction ou rupture non planifiée. Les kystes bénins ne sont pas tous des lésions précancéreuses.</li></ul></div>"},{"i":"c1b657d58d1a","n":44,"o":"44-8","u":"Étiologies","t":"Savoir différencier kystes fonctionnel et organique","q":"Quels sont les critères échographiques de bénignité à rechercher pour différencier un kyste ovarien fonctionnel d'un kyste organique ?","a":"<div class=\"notion-course\"><ul><li>Kyste fonctionnel : lié à l’activité ovarienne, souvent simple et régressif. Une image compatible peut être surveillée selon taille, symptômes et contexte hormonal.</li><li>Kyste organique : lésion persistante ou de nature tumorale, souvent bénigne ; persistance ne signifie pas cancer et n’impose pas à elle seule une chirurgie.</li><li>Échographie : morphologie, caractère uni-/multiloculaire, paroi, cloisons, végétations, composante solide, vascularisation, ascite et contexte ménopausique. Une taille ou un index Doppler isolé ne prouve pas la bénignité.</li><li>IRM en cas de caractérisation indéterminée. La surveillance ou l’intervention dépend de l’ensemble du dossier, du risque de complication et du projet reproductif.</li><li>Une masse suspecte nécessite orientation spécialisée ; éviter ponction ou rupture non planifiée. Les kystes bénins ne sont pas tous des lésions précancéreuses.</li></ul></div>"},{"i":"cd81788cfdf7","n":44,"o":"44-8","u":"Étiologies","t":"Savoir différencier kystes fonctionnel et organique","q":"Comment l'évolution échographique à 3 mois permet-elle de différencier un kyste ovarien fonctionnel d'un kyste organique ?","a":"<div class=\"notion-course\"><ul><li>Kyste fonctionnel : lié à l’activité ovarienne, souvent simple et régressif. Une image compatible peut être surveillée selon taille, symptômes et contexte hormonal.</li><li>Kyste organique : lésion persistante ou de nature tumorale, souvent bénigne ; persistance ne signifie pas cancer et n’impose pas à elle seule une chirurgie.</li><li>Échographie : morphologie, caractère uni-/multiloculaire, paroi, cloisons, végétations, composante solide, vascularisation, ascite et contexte ménopausique. Une taille ou un index Doppler isolé ne prouve pas la bénignité.</li><li>IRM en cas de caractérisation indéterminée. La surveillance ou l’intervention dépend de l’ensemble du dossier, du risque de complication et du projet reproductif.</li><li>Une masse suspecte nécessite orientation spécialisée ; éviter ponction ou rupture non planifiée. Les kystes bénins ne sont pas tous des lésions précancéreuses.</li></ul></div>"},{"i":"edee98780bb9","n":44,"o":"44-8","u":"Étiologies","t":"Savoir différencier kystes fonctionnel et organique","q":"Quelle est la conduite à tenir initiale en présence de tous les critères échographiques de bénignité pour un kyste ovarien ?","a":"<div class=\"notion-course\"><ul><li>Kyste fonctionnel : lié à l’activité ovarienne, souvent simple et régressif. Une image compatible peut être surveillée selon taille, symptômes et contexte hormonal.</li><li>Kyste organique : lésion persistante ou de nature tumorale, souvent bénigne ; persistance ne signifie pas cancer et n’impose pas à elle seule une chirurgie.</li><li>Échographie : morphologie, caractère uni-/multiloculaire, paroi, cloisons, végétations, composante solide, vascularisation, ascite et contexte ménopausique. Une taille ou un index Doppler isolé ne prouve pas la bénignité.</li><li>IRM en cas de caractérisation indéterminée. La surveillance ou l’intervention dépend de l’ensemble du dossier, du risque de complication et du projet reproductif.</li><li>Une masse suspecte nécessite orientation spécialisée ; éviter ponction ou rupture non planifiée. Les kystes bénins ne sont pas tous des lésions précancéreuses.</li></ul></div>"},{"i":"20bf8cc3d34b","n":44,"o":"44-3","u":"Epidémiologie","t":"Fréquence des fibromes et des kystes ovariens bénins","q":"Que retenir concernant fréquence des fibromes et des kystes ovariens bénins ?","a":"<div class=\"notion-course\"><h4><span class=\"nc-yellow_bg\">Fibrome utérin</span></h4>\n      <table>\n        <thead>\n          <tr><th>Item</th><th>Donnée</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span>Prévalence</span></strong></td>\n            <td>Augmente avec l’âge : <span>20–30 %</span> des femmes après <span>35 ans</span> · <span>50 %</span> à<span> 50 ans</span></td>\n          </tr>\n          <tr>\n            <td><strong><span>Évolution</span> spontanée</strong></td>\n            <td>Imprévisible · <strong>régression habituelle après la ménopause</strong></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Kystes ovariens bénins</h4>\n      <table>\n        <thead>\n          <tr><th>Item</th><th>Donnée</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span>Terrain</span></strong></td>\n            <td>Très fréquents pendant la <strong>période d’activité génitale</strong> · l’immense majorité sont des <strong>kystes fonctionnels</strong> bénins</td>\n          </tr>\n          <tr>\n            <td><strong><span>Évolution</span></strong></td>\n            <td>La plupart <strong>régressent spontanément</strong> (contrôle échographique à <span>3 mois</span>) · la persistance &gt; <span>3 mois</span> fait évoquer un kyste <strong>organique</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Bénin <span>vs</span> malin</strong></td>\n            <td>Les tumeurs <span>malignes</span> de l’ovaire restent <strong>rares avant la ménopause</strong> · l’épithélial représente <span>~ 90 %</span> des tumeurs organiques (cf. item 306)</td>\n          </tr>\n        </tbody>\n      </table></div>"},{"i":"32485b2ba9a1","n":44,"o":"44-5","u":"Suivi et/ou pronostic","t":"Connaître les principales complications des fibromes","q":"Que retenir concernant les principales complications des fibromes ?","a":"<div class=\"notion-course\"><h4>Complications douloureuses aiguës</h4>\n\n      <ul>\n        <li><strong><span><span class=\"nc-yellow_bg\">Nécrobiose aseptique</span></span></strong> = principale cause de douleur du fibrome</li>\n        <li><strong><span class=\"nc-orange_bg\">Torsion</span></strong><span class=\"nc-orange_bg\"> d’un fibrome sous-séreux pédiculé</span> (FIGO 7, plus rare)</li>\n        <li><strong>Accouchement par le col</strong> d’un <span class=\"nc-orange_bg\">fibrome pédiculé</span> sous-muqueux avec coliques expulsives (plus rare)</li>\n      </ul>\n\n      <h4><span>Nécrobiose aseptique</span> de fibrome — tableau clinique</h4>\n\n      <table>\n        <thead>\n          <tr><th>Item</th><th>Caractéristique</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Cause</strong></td>\n            <td><strong><span class=\"nc-red nc-bold\">Ischémie du fibrome</span></strong></td>\n          </tr>\n          <tr>\n            <td><strong>Contexte</strong></td>\n            <td>Encore plus fréquente lors de la <strong><span><span class=\"nc-pink_bg\">grossesse</span></span></strong> et du <strong><span class=\"nc-pink_bg\">post-partum</span></strong></td>\n          </tr>\n          <tr>\n            <td><strong>Symptômes</strong></td>\n            <td>\n              <span><span class=\"nc-blue_bg\">Fièvre</span></span><span class=\"nc-blue_bg\"> </span><span><span class=\"nc-blue_bg\">38–39 °C</span></span><br>\n              <span class=\"nc-yellow_bg\">Douleurs pelviennes</span> <strong>intenses</strong><br>\n              <span><span class=\"nc-yellow_bg\">Métrorragies</span></span><span class=\"nc-yellow_bg\"> de sang</span> <strong><span class=\"nc-yellow_bg nc-bold\">noirâtre</span></strong> (parfois)\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span>TV</span></strong></td>\n            <td><span class=\"nc-blue_bg\">Augmentation du volume du fibrome</span> · douloureux à la palpation</td>\n          </tr>\n          <tr>\n            <td><strong><span>Échographie</span></strong></td>\n            <td><span class=\"nc-blue_bg\">Image en </span><em><span class=\"nc-blue_bg\">« cocarde »</span></em> avec <strong><span class=\"nc-blue nc-bold\">hyperéchogénicité centrale</span></strong></td>\n          </tr>\n          <tr>\n            <td><strong>Traitement</strong></td>\n            <td>\n              <strong>Médical</strong> :<br>\n              · Repos au lit + glace sur le ventre<br>\n              · <span><span class=\"nc-pink_bg\">Antalgiques</span></span> + <span><span class=\"nc-pink_bg\">AINS</span></span> (<span>CI si grossesse</span>)<br>\n              · Antibiotiques si surinfection suspectée\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Complications obstétricales et gravidiques</h4>\n\n      <p>Retentissement <em>global modéré</em> une fois la <span><span class=\"nc-pink_bg\">grossesse</span></span> installée, mais risque majoré de <strong><span><span class=\"nc-red\">hospitalisation</span></span>, <span class=\"nc-red\">césarienne</span>, complications du <span class=\"nc-pink_bg\">post-partum</span></strong>.</p>\n\n      <ul>\n        <li><strong><span class=\"nc-orange_bg\">Infertilité</span>, <span class=\"nc-orange_bg\">fausses couches spontanées</span></strong> : si <span class=\"nc-red nc-bold\">fibrome sous-muqueux déformant la cavité</span></li>\n        <li><strong><span><span class=\"nc-red_bg\">Menace</span></span><span class=\"nc-red_bg\"> d’accouchement prématuré / prématurité</span></strong> : si <span class=\"nc-red nc-bold\">nécrobiose aseptique</span> (plus fréquente en <span><span class=\"nc-pink_bg\">grossesse</span></span>)</li>\n        <li><strong><span class=\"nc-red_bg\">Localisation praevia</span></strong> gênant l’accouchement par voie basse</li>\n        <li><strong><span class=\"nc-red_bg\">Présentation dystocique</span></strong> si <span class=\"nc-red_bg\">fibrome volumineux</span> interstitiel</li>\n        <li><strong>Dystocie dynamique / <span class=\"nc-red_bg\">hémorragie de la délivrance</span></strong> : mauvaise rétraction utérine</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège.</strong> Devant <em><span>fièvre</span> + douleur pelvienne intense chez une femme enceinte connue pour un fibrome</em>, évoquer la <strong><span class=\"nc-red nc-bold\">nécrobiose aseptique</span></strong>. <span><span class=\"nc-pink_bg\">AINS</span> contre-indiqués pendant la <span class=\"nc-pink_bg\">grossesse</span></span> — <span><span class=\"nc-pink_bg\">antalgiques</span></span> de palier adapté + repos + glace.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 24 — Complications de la <span><span class=\"nc-green_bg\">grossesse</span></span> · 23 — <span class=\"nc-green_bg\">Grossesse</span> normale</em></p></div>"},{"i":"d054c906128e","n":44,"o":"44-6","u":"Étiologies","t":"Connaître les étiologies des kystes ovarien","q":"Que retenir concernant les étiologies des kystes ovarien ?","a":"<div class=\"notion-course\"><p>Deux grandes familles, qu’il faut absolument distinguer (cf. obj-7) car la conduite à tenir diffère.</p>\n\n      <table>\n        <thead>\n          <tr><th>Famille</th><th>Mécanisme / type</th><th>Exemples</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Kystes fonctionnels</strong><br><em>(les plus fréquents)</em></td>\n            <td>Anomalie d’un follicule au cours du cycle · <strong>régressent spontanément</strong></td>\n            <td>· <strong><span>Kyste folliculaire</span></strong> (follicule non rompu)<br>· <strong><span>Kyste lutéal</span></strong> (corps jaune persistant)</td>\n          </tr>\n          <tr>\n            <td rowspan=\"3\"><strong>Kystes organiques</strong><br><em>(persistants → <span>exérèse</span>)</em></td>\n            <td><strong>Épithéliaux</strong> (<span>~ 90 %</span> des organiques)</td>\n            <td><strong><span>Cystadénome séreux</span></strong>, <strong>mucineux</strong>, endométrioïde · tumeur de Brenner</td>\n          </tr>\n          <tr>\n            <td><strong>Germinaux</strong></td>\n            <td><strong><span>Tératome mature = <span class=\"nc-orange_bg\">kyste dermoïde</span></span></strong> (cheveux, dents, graisse)</td>\n          </tr>\n          <tr>\n            <td><strong>Endométriosique</strong></td>\n            <td><strong><span><span class=\"nc-orange_bg\">Endométriome</span></span></strong> (« kyste chocolat ») → rechercher une <span class=\"nc-red nc-bold\">endométriose</span> profonde associée</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> <em>Fonctionnel</em> = transitoire, <span>surveillance</span> écho à <span>3 mois</span>. <em>Organique</em> = persiste après <span>3 mois</span> → cœlioscopie (<span>kystectomie / annexectomie</span>). Toute zone <strong>solide / végétation</strong> fait craindre une tumeur <span>borderline ou maligne</span>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 306 — Tumeur de l’ovaire · 41 — Endométriose</em></p></div>"},{"i":"ae7523d47f66","n":44,"o":"44-9","u":"Suivi et/ou pronostic","t":"Connaître les principales complications des kystes ovariens","q":"Que retenir concernant les principales complications des kystes ovariens ?","a":"<div class=\"notion-course\"><p>Les complications d’un kyste ovarien sont des <strong>urgences douloureuses</strong> qu’il faut savoir évoquer devant une douleur pelvienne aiguë.</p>\n\n      <table>\n        <thead>\n          <tr><th>Complication</th><th>Caractéristiques</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span>Torsion d’annexe</span></strong></td>\n            <td>La plus grave — <span>urgence</span> chirurgicale (cf. obj-9) · risque de <strong><span>nécrose</span> ovarienne</strong> · favorisée par les kystes lourds (<span>dermoïde</span>)</td>\n          </tr>\n          <tr>\n            <td><strong><span>Hémorragie intra-kystique</span></strong></td>\n            <td>Douleur brutale · hyperdensité du contenu à l’imagerie · le plus souvent résolutive sous traitement médical</td>\n          </tr>\n          <tr>\n            <td><strong><span>Rupture de kyste</span></strong></td>\n            <td>Douleur brutale + <span>épanchement</span> du Douglas · risque d’<span>hémopéritoine</span> si <span>rupture</span> <span>hémorragique</span></td>\n          </tr>\n          <tr>\n            <td><strong>Abcédation / <span class=\"nc-red nc-bold\">infection</span></strong></td>\n            <td>Plus rare · contexte <span>infectieux</span> (<span><span class=\"nc-purple_bg\">abcès</span></span><span class=\"nc-purple_bg\"> ovarien</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Dégénérescence maligne</strong></td>\n            <td>Surtout les kystes <strong>organiques</strong> persistants · à craindre devant une zone solide / végétation</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Réflexe.</strong> Devant une <em>douleur pelvienne aiguë + <span>masse</span> annexielle</em>, penser en premier à la <span>torsion d’annexe</span> (cf. obj-9) — c’est la complication qui impose une <strong><span>chirurgie</span> en <span>urgence</span></strong> pour sauver l’ovaire.\n      </div></div>"},{"i":"1a9b79bc6adc","n":44,"o":"44-11","u":"Examens complémentaires","t":"Connaître les deux principaux examens radiologiques complémentaires à réaliser en cas de tuméfaction pelvienne et leur hiérarchisation (première et deuxième intention)","q":"Que retenir concernant les deux principaux examens radiologiques complémentaires à réaliser en cas de tuméfaction pelvienne et leur hiérarchisation (première et deuxième intention) ?","a":"<div class=\"notion-course\"><h4>Hiérarchisation EDN — <span class=\"nc-yellow_bg\">fibrome utérin</span></h4>\n      <table>\n        <thead>\n          <tr><th>Examen</th><th>Place</th><th>Description sémiologique</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span><span class=\"nc-blue_bg\">Échographie</span></span><span class=\"nc-blue_bg\"> pelvienne</span></strong></td>\n            <td><strong>1ʳᵉ intention</strong> — examen qui fait le diagnostic</td>\n            <td>\n              · Formations <strong>homogènes</strong>, <span>hypoéchogènes</span> par rapport au reste du myomètre<br>\n              · Généralement <strong>bien limitées</strong><br>\n              · <span>Encorbellement vasculaire</span> caractéristique<br>\n              · Nécrobiose : <span>image en « cocarde » avec hyperéchogénicité centrale</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span><span class=\"nc-blue_bg\">IRM</span></span> pelvienne</strong></td>\n            <td><strong>2ᵉ intention</strong></td>\n            <td>\n              Indications :<br>\n              · <span>Masse</span> <span><span class=\"nc-red nc-bold\">&gt; 10 cm</span></span><br>\n              · Nombre de <span class=\"nc-orange_bg\">fibromes</span> <span>&gt; 5</span><br>\n              · <span><span class=\"nc-red nc-bold\">Échographie</span></span><span class=\"nc-red nc-bold\"> insuffisante</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Bilan <span>biologique</span> d’accompagnement</h4>\n      <ul>\n        <li><strong><span>NFS</span> + <span>ferritine</span></strong> : rechercher une anémie ferriprive (complication des ménométrorragies)</li>\n        <li><strong>β-hCG</strong> systématique en âge de procréer avant toute exploration</li>\n        <li><span>Bilan préopératoire</span> si <span>chirurgie</span> envisagée</li>\n      </ul>\n\n      <h4>Hiérarchisation EDN — <span>masse</span> ovarienne</h4>\n      <table>\n        <thead>\n          <tr><th>Examen</th><th>Place</th><th>Apport</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span><span class=\"nc-blue_bg\">Échographie</span></span><span class=\"nc-blue_bg\"> pelvienne</span></strong><br>(sus-pubienne + endovaginale)</td>\n            <td><strong>1ʳᵉ intention</strong></td>\n            <td>Classe la <span>masse</span> : <strong>kyste fonctionnel</strong> <span>vs</span> <strong>organique</strong> <span>vs</span> <strong><span><span class=\"nc-orange_bg\">critères de</span></span><span class=\"nc-orange_bg\"> malignité</span></strong> · recherche d’<span>ascite</span></td>\n          </tr>\n          <tr>\n            <td><strong><span><span class=\"nc-blue_bg\">IRM</span></span> pelvienne</strong></td>\n            <td><strong>2ᵉ intention</strong></td>\n            <td><span class=\"nc-orange_bg\">Origine indéterminée</span> · <span><span class=\"nc-orange_bg\">critères de</span></span><span class=\"nc-orange_bg\"> malignité</span> · <strong><span><span class=\"nc-orange_bg\">masse</span></span><span class=\"nc-orange_bg\"> uniloculaire pure </span><span><span class=\"nc-orange_bg\">&gt; 7 cm</span></span></strong> (Se de l’écho moins bonne sur gros kyste)</td>\n          </tr>\n          <tr>\n            <td><strong><span>TDM</span> abdomino-pelvien</strong></td>\n            <td>Bilan d’extension</td>\n            <td>Si suspicion de <span>malignité</span> / carcinose (atteinte hépatique, <span>adénopathies</span>)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4><span class=\"nc-blue_bg\">Marqueurs tumoraux</span> (si <span>masse</span> suspecte)</h4>\n      <ul>\n        <li><strong><span><span class=\"nc-yellow_bg\">CA-125</span></span></strong> (± <span class=\"nc-yellow_bg\">HE4</span>, <span><span class=\"nc-yellow_bg\">ACE</span></span>, <span>CA 19-9</span>) : devant une tumeur ovarienne suspecte — <em>inutile sur un kyste manifestement bénin</em></li>\n        <li><strong><span><span class=\"nc-blue_bg\">LDH</span></span>, α-fœtoprotéine, <span class=\"nc-blue_bg\">hCG</span></strong> : si suspicion de <strong>tumeur germinale</strong> (femme jeune)</li>\n        <li><strong><span class=\"nc-pink_bg\">Estradiol</span>, AMH, <span class=\"nc-pink_bg\">inhibine B</span></strong> : si signes d’hyperœstrogénie / tumeur de la granulosa</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Synthèse 1ʳᵉ/2ᵉ intention.</strong> Quelle que soit la <span>tuméfaction</span> (utérine ou ovarienne) : <strong><span><span class=\"nc-blue_bg\">échographie pelvienne</span></span> en 1ʳᵉ intention</strong>, <strong><span><span class=\"nc-blue_bg\">IRM</span></span> en 2ᵉ intention</strong> sur les masses complexes / volumineuses / indéterminées. Précéder de la <span><span class=\"nc-pink nc-bold\">β-hCG</span></span> en âge de procréer.\n      </div></div>"},{"i":"e34afb31c742","n":44,"o":"44-13","u":"Définition","t":"Définir les différents compartiments du prolapsus","q":"Que retenir concernant définir les différents compartiments du prolapsus ?","a":"<div class=\"notion-course\"><p>Deux nomenclatures coexistent (selon que l’on décrit la <em>paroi vaginale</em> qui descend ou <em>l’organe</em> qui bombe).</p>\n\n      <table>\n        <thead>\n          <tr><th>Étage</th><th>Paroi vaginale (colpocèle)</th><th>Organe extériorisé</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Antérieur</strong></td>\n            <td>Colpocèle antérieur (face antérieure du <span class=\"nc-yellow_bg nc-bold\">vagin</span>)</td>\n            <td><strong><span><span class=\"nc-blue_bg\">Cystocèle</span></span></strong> = <em><span class=\"nc-purple nc-bold\">vessie</span></em></td>\n          </tr>\n          <tr>\n            <td><strong>Moyen</strong></td>\n            <td>Colpocèle apical (apex du <span class=\"nc-yellow_bg nc-bold\">vagin</span>)</td>\n            <td><strong><span>Hystérocèle / hystéroptose</span></strong> = <em><span class=\"nc-purple nc-bold\">utérus</span></em></td>\n          </tr>\n          <tr>\n            <td rowspan=\"3\"><strong>Postérieur</strong></td>\n            <td rowspan=\"3\">Colpocèle postérieur (face postérieure du <span class=\"nc-yellow_bg nc-bold\">vagin</span>)</td>\n            <td><strong><span><span class=\"nc-blue_bg\">Rectocèle</span></span></strong> = <em><span class=\"nc-purple nc-bold\">rectum</span></em></td>\n          </tr>\n          <tr><td><strong><span><span class=\"nc-blue_bg\">Élytrocèle</span></span></strong> = <em>cul-de-sac recto-utérin (Douglas)</em></td></tr>\n          <tr><td><strong><span>Entérocèle</span></strong> = <em>intestin</em></td></tr>\n        </tbody>\n      </table></div>"},{"i":"02050a3bbe8b","n":44,"o":"44-14","u":"Diagnostic positif","t":"Citer les diagnostics différentiels du prolapsus génital de la femme","q":"Que retenir concernant citer les diagnostics différentiels du prolapsus génital de la femme ?","a":"<div class=\"notion-course\"><p>Devant une <strong><span>tuméfaction vaginale</span> extériorisée</strong>, plusieurs diagnostics imitent le prolapsus. Le <span>TV</span>/TR et l’<span>échographie</span> aident à les écarter.</p>\n\n      <ul>\n        <li><strong><span><span class=\"nc-orange nc-bold\">Kyste vaginal</span></span></strong> (ex. kyste du canal de Gartner)</li>\n        <li><strong><span><span class=\"nc-orange nc-bold\">Fibrome de la cloison vésico-vaginale</span></span></strong> / fibrome accouché par le col</li>\n        <li><strong><span>Polype cervical extériorisé</span></strong></li>\n        <li><strong><span><span class=\"nc-red nc-bold\">Ascite</span></span></strong> : peut <em>provoquer ou aggraver</em> l’extériorisation d’un prolapsus</li>\n        <li><strong><span>Prolapsus rectal</span></strong> (extériorisation du <span class=\"nc-purple nc-bold\">rectum</span> <em>par l’anus</em> — à ne pas confondre avec une <span class=\"nc-blue_bg\">rectocèle</span>)</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Démarche.</strong> <span><span class=\"nc-blue_bg\">Échographie abdomino-pelvienne</span></span> souvent demandée pour <em>éliminer</em> un <span class=\"nc-orange nc-bold\">kyste vaginal</span>, un <span class=\"nc-orange nc-bold\">fibrome de la cloison vésico-vaginale</span> ou une <span class=\"nc-red nc-bold\">ascite</span>. Au <span>TV</span>/TR, le prolapsus <strong>ne contient pas de <span>masse</span></strong> propre — c’est un point distinctif.\n      </div></div>"},{"i":"d025db5a49ec","n":44,"o":"44-15","u":"Epidémiologie","t":"Connaître la fréquence du prolapsus","q":"Que retenir concernant la fréquence du prolapsus ?","a":"<div class=\"notion-course\"><table>\n        <thead>\n          <tr><th>Âge</th><th><span>Prévalence</span></th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Jusqu’à<span> 50 ans</span></strong></td>\n            <td>Augmente avec l’âge : <span>3–11 %</span> au questionnaire <span>vs</span> <span>30–90 %</span> cliniquement</td>\n          </tr>\n          <tr>\n            <td><strong>Après <span>50 ans</span></strong></td>\n            <td><span>Prévalence</span> <strong>stable</strong>, mais le <strong><span><span class=\"nc-red nc-bold\">grade</span></span><span class=\"nc-red nc-bold\"> du prolapsus augmente</span></strong><span class=\"nc-red nc-bold\"> avec l’âge</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> L’écart majeur entre <span>prévalence</span> <em>au questionnaire</em> (<span>3–11 %</span>) et <em>clinique</em> (<span>30–90 %</span>) explique qu’un <strong>grand nombre de prolapsus sont asymptomatiques</strong>. Le traitement n’est proposé que <em>si la patiente est gênée</em>. <em>(FR détaillés dans l’onglet « Astuces PU &amp; Pièges ».)</em>\n      </div></div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/2ad37f85d941811480afc5512de0060f?pvs=204","reviewedAt":"2026-10-15","note":"Cours personnel, couleurs des passages Notion correspondants, corrections et parcours interactifs sourcés. Les compléments sont distingués des figures d’origine."}};
